#[derive(Clone, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
struct WorklistAuthorizationRecord {
    // "approved" | "drop" | "none" | "direct-edit"
    kind: String,
    #[serde(default)]
    ids: Vec<String>,
    // Full resolved item objects (metadata + draft prose + feedback) for the
    // approved/drop ids found on disk. The agent reads these via /__worklist/resolve
    // instead of re-reading worklist.json. Empty for legacy `{ids:[...]}` drops.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    items: Vec<serde_json::Value>,
    issued_at_ms: i64,
    source: String,
    #[serde(default)]
    consumed_at_ms: Option<i64>,
    // security-h4: set when an interrupt/cancel (Esc, menu-reject, provider
    // cancel) abandons the turn before the agent reached mutate/commit.
    // Distinct from consumed_at_ms — a drop's resolve consumes on read but
    // the same-turn prune must still succeed, so consumption cannot gate
    // mutate. An interrupted record is fail-closed: mutate and commit reject
    // it. #[serde(default)] so pre-H4 auth files load.
    #[serde(default)]
    interrupted_at_ms: Option<i64>,
    // one-shot Approve & commit (judell/bram#241): set when the approval's
    // gate was "apply-and-commit". The commit route then accepts still-
    // `proposed` ids (advance folded into commit) under this single auth read.
    #[serde(default)]
    commit_too: bool,
}

// security-h4: TTL bounding how long an approved/drop authorization stays
// valid for a mutate/commit, so a stale record left on disk by an abandoned
// turn can't be replayed on a later one. Sized to fit real implementation
// time, NOT a tight "same turn" proxy: a legitimate approve → agent
// implements + tests for several minutes → advance flow must not be rejected
// (a 5-minute window did reject one on 2026-07-14). The sharper H4 control is
// the interrupted_at_ms fail-closed gate, which is independent of this TTL.
const WORKLIST_AUTH_TTL_MS: i64 = 30 * 60 * 1000;

#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
struct PendingWorklistPushMirror {
    item_id: String,
    issue: u64,
    commit_sha: String,
    changelog: String,
    created_at_ms: i64,
}

// close-on-push-automatic (security H5): a pending issue-close intent recorded
// at the commit gate from the user's close-on-commit dialog selections, bound
// to that commit's SHA. Nothing closes at commit time; on the user's explicit
// Push, flush_pending_issue_closes closes each issue whose commit is now
// visible on origin. Independent of the lifecycle-mirror (comment) queue.
#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
struct PendingIssueClose {
    issue: u64,
    commit_sha: String,
    #[serde(default)]
    comment: Option<String>,
    // issue-close-queue-survives-rebase: stable patch-id recorded at the
    // commit gate. The Push button's auto-rebase rewrites SHAs (live
    // occurrence 2026-07-23: #227's bc881b8 became d0f184f and the queued
    // close silently deferred forever), so the flush re-anchors an
    // absent-SHA record to the origin commit with the same patch-id —
    // content-derived and rebase-stable. Optional for legacy records.
    #[serde(default)]
    patch_id: Option<String>,
    created_at_ms: i64,
}

// Single opt-out phrase (opt-out-single-phrase-and-audit): narrowed from a
// seven-phrase list to the one explicit phrase, mirrored verbatim in
// claude-worklist-guard.py's and codex-worklist-guard.py's
// _OPT_OUT_PATTERNS. The Skip worklist button / `skip-worklist:` prefix
// remain a separate, non-verbal route unaffected by this function.
fn turn_text_has_direct_edit_opt_out(text: &str) -> bool {
    let lower = text.to_ascii_lowercase();
    lower.contains("just do it")
}

// Cross-platform home directory: $HOME on Unix, %USERPROFILE% on Windows.
// Returned as PathBuf so callers can .join() directly without re-parsing.
fn home_dir() -> Option<PathBuf> {
    std::env::var_os("HOME")
        .or_else(|| std::env::var_os("USERPROFILE"))
        .map(PathBuf::from)
}

fn expand_tilde(p: &str) -> String {
    if let Some(rest) = p.strip_prefix("~/") {
        if let Some(home) = home_dir() {
            return format!("{}/{}", home.display(), rest);
        }
    }
    p.to_string()
}

fn shell_single_quote(s: &str) -> String {
    format!("'{}'", s.replace('\'', "'\\''"))
}

fn wsl_model_path_arg(model_path: &str) -> String {
    if let Some(rest) = model_path.strip_prefix("~/") {
        format!(
            "\"$HOME/{}\"",
            rest.replace('\\', "\\\\").replace('"', "\\\"")
        )
    } else {
        shell_single_quote(model_path)
    }
}

fn wsl_distro_args() -> Vec<String> {
    match first_nonempty_env(&["BRAM_WSL_DISTRO"]) {
        Some(distro) => vec!["-d".to_string(), distro, "--".to_string()],
        None => Vec::new(),
    }
}

fn command_output_lossy(output: &std::process::Output) -> String {
    let mut text = String::new();
    text.push_str(&String::from_utf8_lossy(&output.stdout));
    text.push_str(&String::from_utf8_lossy(&output.stderr));
    text.replace('\0', "").trim().to_string()
}

fn whisper_trace<R: tauri::Runtime>(app: &AppHandle<R>, body: &str) {
    eprintln!("[whisper] {}", body);
    append_bram_trace_line(app, "whisper", body);
}

fn trace_whisper_env<R: tauri::Runtime>(app: &AppHandle<R>) {
    let mut body = format!(
        "env platform={} arch={}",
        std::env::consts::OS,
        std::env::consts::ARCH
    );
    if cfg!(target_os = "windows") {
        let distro =
            first_nonempty_env(&["BRAM_WSL_DISTRO"]).unwrap_or_else(|| "(default)".to_string());
        let version = std::process::Command::new("wsl.exe")
            .arg("--version")
            .output()
            .ok()
            .map(|out| command_output_lossy(&out))
            .and_then(|s| s.lines().next().map(|line| line.to_string()))
            .unwrap_or_else(|| "(unavailable)".to_string());
        body.push_str(&format!(" wsl_distro={} wsl_version={:?}", distro, version));
    }
    whisper_trace(app, &body);
}

// Active project root — resolved once at startup from a CLI arg
// (bram /path/to/project) or std::env::current_dir(). Read by
// the HTTP server, watcher, git/sessions/PTY commands.
struct ActiveProjectState(Mutex<PathBuf>);

// URLs for the two iframes.
//
// `tools` is always the internal loopback (Bram's own server,
// serving /__tools/index.html, /__shell/*, embedded assets, git/issues
// endpoints, etc.).
//
// `right_pane` is now always `tauri://localhost/__project/index.html`
// regardless of project configuration. The tauri:// scheme handler in
// `handle_tauri_scheme` intercepts paths under `/__project/*` and
// proxies them to `right_pane_upstream` (loopback default, or external
// dev server when `.bram.json` (or legacy `.xmlui-desktop.json`) declares one). Net effect: the
// right-pane iframe is same-origin with the shell, while the actual
// bytes still come from the upstream.
//
// `right_pane_upstream` is the proxy target (always ends with `/`).
//
// Service workers (used by MSW and xmlui's apiInterceptor) require a
// secure-context origin. Custom URI schemes are not secure contexts on
// macOS, so SW capability is lost in the right-pane iframe on macOS.
// Acceptable for normal apps; playground apps that synthesize APIs
// will not work in xd on macOS — see worklist item
// `same-origin-iframe-via-tauri-scheme-proxy` for the full discussion.
struct PaneUrlsState(Mutex<PaneUrls>);

#[derive(Default, Clone)]
struct PaneUrls {
    right_pane: String,
    tools: String,
    // Loopback-served URL used when no project server is declared. Used by
    // the agent-tools drawer's right-pane-info display (so the user sees
    // the actual upstream URL, not the tauri:// proxy URL) and as the
    // fallback upstream after the server block is removed from
    // project config at runtime.
    default_right_pane: String,
    // Base URL the tauri:// scheme handler proxies right-pane requests to.
    // Always ends with `/`. Switches between the loopback default and an
    // external server based on project config at startup and on
    // config reload.
    right_pane_upstream: String,
    // Always the internal-loopback base URL (ends with `/`), regardless of
    // any external dev-server declared in project config. Used by the
    // scheme handler to route xd-internal `/__*` requests (sessions,
    // worklist, app-info, etc.) — these never live on the project's dev
    // server even when one is declared.
    loopback_origin: String,
}

