// legacy .xmlui-desktop.json accepted as a migration alias. Distinct
// from XMLUI's own config.json (the app-under-test isn't necessarily
// an XMLUI app). All fields optional.
#[derive(Default, Clone, serde::Deserialize)]
struct ProjectConfig {
    #[serde(default, rename = "mirrorWorklistLifecycleToIssue")]
    mirror_worklist_lifecycle_to_issue: Option<bool>,
    #[serde(default)]
    server: Option<ServerConfig>,
    #[serde(default)]
    shell: Option<ShellConfig>,
    #[serde(default)]
    worklist: Option<WorklistConfig>,
    #[serde(default)]
    ui: Option<UiConfig>,
    #[serde(default)]
    traces: Option<TracesConfig>,
    #[serde(default)]
    menus: Option<MenusConfig>,
    #[serde(default)]
    ai: Option<AiConfig>,
    #[serde(default)]
    search: Option<SearchConfig>,
    // issue-355: project-designated SQLite database for the read-only
    // /query route, relative to the project root. Explicit opt-in is the
    // security posture — the route exposes nothing until this is set, and
    // it can never reach Bram's own databases (the search index holds
    // transcript content).
    #[serde(default)]
    db: Option<String>,
}
