fn draft_markdown_path(dir: &Path, id: &str) -> Option<PathBuf> {
    if id.is_empty() || id.contains('/') || id.contains('\\') {
        return None;
    }
    Some(dir.join(format!("{}.md", id)))
}

fn feedback_draft_path(drafts_dir: &Path, feedback_id: &str) -> Option<PathBuf> {
    draft_markdown_path(drafts_dir, feedback_id)
}

fn feedback_draft_belongs_to_item(file_name: &str, item_id: &str) -> bool {
    file_name == format!("{}.md", item_id) || file_name.ends_with(&format!("-{}.md", item_id))
}

// Resolve one feedbackRef ("<unix_ms>-<itemId>") to its .md body, checking
// the live draft (resources/feedback-drafts/) first, then the promoted copy
// (resources/feedback-history/). Reconstructs the filename from the ref — no
// caller-supplied path, so no traversal. Serves the Transcript's
// iterate-feedback display and any other consumer holding a feedbackRef.
fn feedback_content_by_ref<R: tauri::Runtime>(app: &AppHandle<R>, fref: &str) -> Option<String> {
    if fref.is_empty() || fref.contains('/') || fref.contains('\\') {
        return None;
    }
    for dir in [feedback_drafts_dir(app), feedback_history_dir(app)] {
        if let Some(dir) = dir {
            if let Ok(s) = std::fs::read_to_string(dir.join(format!("{}.md", fref))) {
                return Some(s);
            }
        }
    }
    None
}

// Build a { feedbackRef: text } map across feedback-drafts/ + feedback-history/,
// most-recent `limit` by the <unix_ms>- filename prefix. A ref lives in exactly
// one dir at a time (drafts until promoted on advance/prune, history after), so
// a plain union is correct. Lets the Transcript resolve iterate feedback (which
// rides a feedbackRef, not inline) with one fetch + O(1) lookup.
fn feedback_ref_map<R: tauri::Runtime>(app: &AppHandle<R>, limit: usize) -> serde_json::Value {
    let mut rows: Vec<(u64, String, String)> = Vec::new();
    for dir in [feedback_drafts_dir(app), feedback_history_dir(app)] {
        let Some(dir) = dir else { continue };
        let Ok(read) = std::fs::read_dir(&dir) else {
            continue;
        };
        for entry in read.flatten() {
            let Ok(name) = entry.file_name().into_string() else {
                continue;
            };
            let Some(stem) = name.strip_suffix(".md") else {
                continue;
            };
            let ts: u64 = stem
                .split_once('-')
                .and_then(|(t, _)| t.parse().ok())
                .unwrap_or(0);
            let body = std::fs::read_to_string(entry.path()).unwrap_or_default();
            rows.push((ts, stem.to_string(), body.trim().to_string()));
        }
    }
    rows.sort_by(|a, b| b.0.cmp(&a.0));
    rows.truncate(limit.max(1));
    let mut map = serde_json::Map::new();
    for (_ts, fref, body) in rows {
        map.entry(fref)
            .or_insert_with(|| serde_json::Value::String(body));
    }
    serde_json::Value::Object(map)
}

fn unique_feedback_history_path(history_dir: &Path, file_name: &str) -> PathBuf {
    let initial = history_dir.join(file_name);
    if !initial.exists() {
        return initial;
    }
    let stem = file_name.strip_suffix(".md").unwrap_or(file_name);
    for n in 1..1000 {
        let candidate = history_dir.join(format!("{}-{}.md", stem, n));
        if !candidate.exists() {
            return candidate;
        }
    }
    history_dir.join(format!("{}-{}.md", stem, unix_now_ms()))
}

fn promote_feedback_drafts_for_items<R: tauri::Runtime>(
    app: &AppHandle<R>,
    item_ids: &[String],
    reason: &str,
) {
    if item_ids.is_empty() {
        return;
    }
    let Some(drafts_dir) = feedback_drafts_dir(app) else {
        return;
    };
    let Ok(entries) = std::fs::read_dir(&drafts_dir) else {
        return;
    };
    let Some(history_dir) = feedback_history_dir(app) else {
        return;
    };
    let mut matched: Vec<(PathBuf, String, String)> = Vec::new();
    for entry in entries.flatten() {
        let path = entry.path();
        if !path.is_file() {
            continue;
        }
        let file_name = entry.file_name().to_string_lossy().to_string();
        if let Some(item_id) = item_ids
            .iter()
            .find(|id| feedback_draft_belongs_to_item(&file_name, id))
        {
            matched.push((path, file_name, item_id.clone()));
        }
    }
    if matched.is_empty() {
        return;
    }
    if let Err(e) = std::fs::create_dir_all(&history_dir) {
        if bram_trace_enabled() {
            append_bram_trace_line(
                app,
                "feedback-draft",
                &format!("op=promote-dir-failed reason={} error={}", reason, e),
            );
        }
        return;
    }
    for (path, file_name, item_id) in matched {
        let dest = unique_feedback_history_path(&history_dir, &file_name);
        match std::fs::rename(&path, &dest) {
            Ok(()) => {
                if bram_trace_enabled() {
                    append_bram_trace_line(
                        app,
                        "feedback-draft",
                        &format!(
                            "op=promote reason={} item_id={} feedback_id={}",
                            reason,
                            item_id,
                            file_name.strip_suffix(".md").unwrap_or(&file_name)
                        ),
                    );
                }
            }
            Err(e) => {
                if bram_trace_enabled() {
                    append_bram_trace_line(
                        app,
                        "feedback-draft",
                        &format!(
                            "op=promote-failed reason={} item_id={} feedback_id={} error={}",
                            reason,
                            item_id,
                            file_name.strip_suffix(".md").unwrap_or(&file_name),
                            e
                        ),
                    );
                }
            }
        }
    }
}

