    // Test-local shim: the commit filter asks "is this declared entry covered
    // by anything staged", which is staged_path_covered_by applied across the
    // staged list.
    fn staged_path_covered_by_any(entry: &str, staged: &[String]) -> bool {
        staged.iter().any(|s| staged_path_covered_by(entry, s))
    }

    #[test]
    fn batched_diff_splits_into_per_file_bodies() {
        // issue-317: batching must not cost the per-file cap_patch treatment,
        // so one `git diff` over many paths is split back apart by header.
        let batched = "diff --git a/src/a.rs b/src/a.rs\nindex 111..222 100644\n--- a/src/a.rs\n+++ b/src/a.rs\n@@ -1 +1 @@\n-old\n+new\ndiff --git a/docs/b.md b/docs/b.md\nindex 333..444 100644\n--- a/docs/b.md\n+++ b/docs/b.md\n@@ -1 +1 @@\n-x\n+y\n";
        let parts = split_diff_by_file(batched);
        assert_eq!(parts.len(), 2, "{parts:?}");
        assert_eq!(parts[0].0, "src/a.rs");
        assert_eq!(parts[1].0, "docs/b.md");
        assert!(parts[0].1.contains("+new"), "{}", parts[0].1);
        assert!(!parts[0].1.contains("docs/b.md"), "bodies must not bleed");
        assert!(parts[1].1.contains("+y"), "{}", parts[1].1);
    }

    #[test]
    fn batched_diff_split_handles_quoted_paths_and_empty_input() {
        // git quotes paths that need escaping; the key must match what the
        // item declared.
        let batched = "diff --git \"a/we ird.txt\" \"b/we ird.txt\"\n@@ -1 +1 @@\n+z\n";
        let parts = split_diff_by_file(batched);
        assert_eq!(parts.len(), 1);
        assert_eq!(parts[0].0, "we ird.txt");
        assert!(split_diff_by_file("").is_empty());
    }

    #[test]
    fn declared_directory_is_carried_into_the_commit_pathspec() {
        // issue-312 repro: an item declaring a directory staged 59 files and
        // committed 1, because the directory is never literally in git's
        // staged FILE list. Prefix matching carries it.
        let staged = ids(&[
            "resources/worklist.json",
            "resources/worklist-drafts/a.md",
            "resources/worklist-drafts/b.md",
            "resources/worklist-history/2026.json",
        ]);
        assert!(staged_path_covered_by_any(
            "resources/worklist.json",
            &staged
        ));
        assert!(staged_path_covered_by_any(
            "resources/worklist-drafts",
            &staged
        ));
        assert!(staged_path_covered_by_any(
            "resources/worklist-drafts/",
            &staged
        ));
        assert!(staged_path_covered_by_any(
            "resources/worklist-history",
            &staged
        ));
        // A never-staged path stays excluded, so `git commit -- <path>` is
        // never handed a pathspec matching nothing.
        assert!(!staged_path_covered_by_any("resources/gone.md", &staged));
        // A prefix that is not a path boundary must not match.
        assert!(!staged_path_covered_by_any("resources/worklist", &staged));
    }

    #[test]
    fn staged_deletion_still_matches_by_exact_path() {
        // The exact-match arm is why this filter exists at all
        // (worklist-commit-omits-staged-deletions): a deletion staged by the
        // apply appears in staged_after by its exact path.
        let staged = ids(&["app/tools/components/Feedback.xmlui"]);
        assert!(staged_path_covered_by_any(
            "app/tools/components/Feedback.xmlui",
            &staged
        ));
    }

    #[test]
    fn left_behind_detects_staged_paths_no_pathspec_covers() {
        let staged = ids(&[
            "resources/worklist.json",
            "resources/worklist-drafts/a.md",
            "resources/worklist-drafts/b.md",
        ]);
        // The pre-fix behavior: only the plain file in the pathspec.
        let left = staged_paths_left_behind(&ids(&["resources/worklist.json"]), &staged);
        assert_eq!(
            left.len(),
            2,
            "both draft files should be reported: {left:?}"
        );
        // The fixed behavior: the directory covers its contents, nothing left.
        let none = staged_paths_left_behind(
            &ids(&["resources/worklist.json", "resources/worklist-drafts"]),
            &staged,
        );
        assert!(none.is_empty(), "unexpected leftovers: {none:?}");
    }

    #[test]
    fn worklist_commit_add_args_stage_deletions() {
        // A deletion-bearing file list must reach `git add` with -A so a
        // tracked file already removed from the working tree stages as a
        // removal instead of failing the pathspec match (the bug that
        // blocked committing the Feedback.xmlui deletion).
        let files = ids(&["src/a.rs", "app/tools/components/Feedback.xmlui"]);
        let args = worklist_commit_add_args(&files);
        assert_eq!(
            args,
            ids(&[
                "add",
                "-A",
                "--",
                "src/a.rs",
                "app/tools/components/Feedback.xmlui"
            ])
        );
    }

    #[test]
    fn worklist_commit_rejects_unrelated_staged_files() {
        let approved = ids(&["src/a.rs", "docs/a.md"]);
        ensure_no_unrelated_staged_files(&ids(&["src/a.rs"]), &approved)
            .expect("approved staged files are fine");

        let err = ensure_no_unrelated_staged_files(&ids(&["src/a.rs", "src/other.rs"]), &approved)
            .expect_err("unrelated staged files are refused");
        assert_eq!(
            err,
            "refusing worklist commit because unrelated files are staged: src/other.rs"
        );
    }

    #[test]
    fn worklist_commit_accepts_files_under_declared_directory() {
        // #295: `git add` expands a declared directory to its contents;
        // the verification must agree instead of refusing what it staged.
        let approved = ids(&["docs/a.md", "resources/worklist-drafts"]);
        ensure_no_unrelated_staged_files(
            &ids(&[
                "docs/a.md",
                "resources/worklist-drafts/item-one.md",
                "resources/worklist-drafts/nested/deep.md",
            ]),
            &approved,
        )
        .expect("files under a declared directory are related");

        // A trailing slash on the declared entry behaves the same.
        ensure_no_unrelated_staged_files(
            &ids(&["resources/worklist-drafts/item-one.md"]),
            &ids(&["resources/worklist-drafts/"]),
        )
        .expect("trailing slash on the declared entry is normalized");

        // Prefix match requires a path separator: `foo` is not `foobar`,
        // and a genuinely foreign staged file is still refused.
        let err = ensure_no_unrelated_staged_files(
            &ids(&["resources/worklist-drafts-archive/old.md", "src/other.rs"]),
            &ids(&["resources/worklist-drafts"]),
        )
        .expect_err("sibling-prefix and foreign staged files are refused");
        assert_eq!(
            err,
            "refusing worklist commit because unrelated files are staged: \
             resources/worklist-drafts-archive/old.md, src/other.rs"
        );
    }

    #[test]
    fn approved_prune_requires_applied_status() {
        let proposed_items = vec![json!({"id": "a", "status": "proposed"})];
        let applied_items = vec![json!({"id": "a", "status": "applied"})];

        let err = validate_post_commit_prune_status(
            "prune",
            "approved",
            false,
            &ids(&["a"]),
            &proposed_items,
        )
        .expect_err("approved prune is post-commit only");
        assert_eq!(
            err,
            "post-commit prune requires applied status: a is proposed"
        );

        validate_post_commit_prune_status("prune", "approved", false, &ids(&["a"]), &applied_items)
            .expect("applied item can be pruned after commit");

        // One-click apply-and-commit (commit_too) prunes a still-proposed item:
        // the same auth authorized committing it, so the prune must accept it.
        validate_post_commit_prune_status("prune", "approved", true, &ids(&["a"]), &proposed_items)
            .expect("commit_too authorizes pruning a proposed item after the one-shot commit");
    }

    #[test]
    fn advance_rejects_non_applied_status() {
        validate_worklist_advance_status("advance", "applied")
            .expect("applied is the only active advance target");

        let err = validate_worklist_advance_status("advance", "committed")
            .expect_err("committed items should be pruned, not advanced");
        assert_eq!(
            err,
            "unsupported advance status: committed; use op:\"prune\" after a successful commit"
        );

        let err = validate_worklist_advance_status("advance", "proposed")
            .expect_err("advancing to proposed is undefined");
        assert_eq!(
            err,
            "unsupported advance status: proposed; use op:\"prune\" after a successful commit"
        );

        validate_worklist_advance_status("prune", "committed")
            .expect("prune does not use target status");
    }

    #[test]
    fn apply_worklist_mutation_advances_and_prunes_only_requested_items() {
        let mut items = vec![
            json!({"id": "a", "status": "proposed"}),
            json!({"id": "b", "status": "proposed"}),
        ];

        let advanced = apply_worklist_mutation(&mut items, "advance", &ids(&["a"]), "applied");
        assert_eq!(advanced, ids(&["a"]));
        assert_eq!(
            items[0].get("status").and_then(|v| v.as_str()),
            Some("applied")
        );
        assert_eq!(
            items[1].get("status").and_then(|v| v.as_str()),
            Some("proposed")
        );

        let pruned = apply_worklist_mutation(&mut items, "prune", &ids(&["a"]), "applied");
        assert_eq!(pruned, ids(&["a"]));
        assert_eq!(items.len(), 1);
        assert_eq!(items[0].get("id").and_then(|v| v.as_str()), Some("b"));
    }

    #[test]
    fn classify_worklist_removals_separates_authorized_drop_from_revert() {
        use std::collections::HashSet;
        let prior = vec![
            json!({"id": "a", "status": "proposed"}),
            json!({"id": "b", "status": "proposed"}),
            json!({"id": "c", "status": "applied"}),
        ];
        // 'a' and 'c' removed; 'b' retained.
        let current = vec![json!({"id": "b", "status": "proposed"})];

        // Live drop auth covering 'a': authorized drop, no violation. 'c' was
        // applied, so its removal is allowed unconditionally (post-commit prune).
        let drop_ids: HashSet<String> = ["a".to_string()].into_iter().collect();
        let (dropped, violations) =
            classify_worklist_removals(&prior, &current, Some("drop"), &drop_ids);
        assert_eq!(dropped, ids(&["a"]));
        assert!(
            violations.is_empty(),
            "applied removals are never violations"
        );

        // No live auth — the consumed-auth state the false-success-drop race
        // produces. The same proposed 'a' removal is now an unauthorized
        // removal the watcher would revert. The last_worklist_cell claim in
        // handle_worklist_mutate prevents the watcher from ever reaching this
        // classification for an authorized drop.
        let empty: HashSet<String> = HashSet::new();
        let (dropped, violations) = classify_worklist_removals(&prior, &current, None, &empty);
        assert!(dropped.is_empty());
        assert_eq!(violations, vec![("a".to_string(), "proposed".to_string())]);
    }

    #[test]
    fn inflight_claim_fully_covered_requires_nonempty_and_all_covered() {
        let claimed = ids(&["a", "b"]);
        // Every claimed id present in mutated -> covered (clear + emit).
        assert!(inflight_claim_fully_covered(
            &claimed,
            &ids(&["a", "b", "c"])
        ));
        // Partial coverage -> not covered (don't clear the sentinel).
        assert!(!inflight_claim_fully_covered(&claimed, &ids(&["a"])));
        // Empty/absent claim -> not covered. This is the #133 skipped-resolve
        // case: no sentinel was written, so the mutate caller must emit its own
        // reconcile signal rather than relying on the clear.
        assert!(!inflight_claim_fully_covered(&ids(&[]), &ids(&["a"])));
    }

