#[cfg(test)]
mod project_config_tests {
    use super::{
        legacy_hook_referencing_sources, project_config_batch_commit_actions,
        project_config_describe_commands, project_config_mirror_worklist_lifecycle_to_issue,
        ProjectConfig,
    };

    fn flag(json: &str) -> bool {
        let config = serde_json::from_str::<ProjectConfig>(json).ok();
        project_config_batch_commit_actions(config)
    }

    #[test]
    fn batch_commit_actions_defaults_to_false() {
        assert!(flag(r#"{ "worklist": { "batchCommitActions": true } }"#));
        assert!(!flag(r#"{ "worklist": { "batchCommitActions": false } }"#));
        assert!(!flag(r#"{ "worklist": {} }"#));
        assert!(!flag(r#"{}"#));
        assert!(!flag(r#"{ "worklist": "#));
        assert!(!project_config_batch_commit_actions(None));
    }

    #[test]
    fn lifecycle_issue_mirror_defaults_to_false() {
        let on =
            serde_json::from_str::<ProjectConfig>(r#"{ "mirrorWorklistLifecycleToIssue": true }"#)
                .ok();
        let off =
            serde_json::from_str::<ProjectConfig>(r#"{ "mirrorWorklistLifecycleToIssue": false }"#)
                .ok();
        assert!(project_config_mirror_worklist_lifecycle_to_issue(on));
        assert!(!project_config_mirror_worklist_lifecycle_to_issue(off));
        assert!(!project_config_mirror_worklist_lifecycle_to_issue(
            serde_json::from_str::<ProjectConfig>(r#"{}"#).ok()
        ));
        assert!(!project_config_mirror_worklist_lifecycle_to_issue(None));
    }

    #[test]
    fn tool_descriptions_require_explicit_project_opt_in() {
        let on =
            serde_json::from_str::<ProjectConfig>(r#"{ "ai": { "describeCommands": true } }"#).ok();
        let off =
            serde_json::from_str::<ProjectConfig>(r#"{ "ai": { "describeCommands": false } }"#)
                .ok();
        assert!(project_config_describe_commands(on));
        assert!(!project_config_describe_commands(off));
        assert!(!project_config_describe_commands(
            serde_json::from_str::<ProjectConfig>(r#"{}"#).ok()
        ));
        assert!(!project_config_describe_commands(None));
    }

    // issue-227: the legacy-shim prune must respect every settings source
    // Claude Code merges, not just the project settings.json.
    #[test]
    fn legacy_hook_prune_held_by_any_source_reference() {
        let needle = "hooks/worklist-guard.py";
        let sources = vec![
            ("project settings.json".to_string(), r#"{"hooks":{"PreToolUse":[{"hooks":[{"command":"$CLAUDE_PROJECT_DIR/.claude/hooks/claude-worklist-guard.py"}]}]}}"#.to_string()),
            ("settings.local.json".to_string(), String::new()),
            ("~/.claude/settings.json".to_string(), r#"{"hooks":{"PreToolUse":[{"hooks":[{"command":"$CLAUDE_PROJECT_DIR/.claude/hooks/worklist-guard.py"}]}]}}"#.to_string()),
        ];
        // The global reference holds the prune back — and containment is
        // exact: the new claude- prefixed command in the project file does
        // NOT match the legacy needle.
        assert_eq!(
            legacy_hook_referencing_sources(&sources, needle),
            vec!["~/.claude/settings.json".to_string()]
        );
    }

    #[test]
    fn legacy_hook_prune_proceeds_when_no_source_references() {
        let needle = "hooks/worklist-guard.py";
        let sources = vec![
            ("project settings.json".to_string(), r#"{"hooks":{"PreToolUse":[{"hooks":[{"command":"$CLAUDE_PROJECT_DIR/.claude/hooks/claude-worklist-guard.py"}]}]}}"#.to_string()),
            ("settings.local.json".to_string(), String::new()),
            ("~/.claude/settings.json".to_string(), r#"{"model":"claude-fable-5"}"#.to_string()),
        ];
        assert!(legacy_hook_referencing_sources(&sources, needle).is_empty());
    }

    #[test]
    fn legacy_hook_prune_missing_sources_read_as_empty() {
        // Missing files arrive as empty strings (read_to_string fallback):
        // never a reference, never a crash.
        let sources = vec![
            ("project settings.json".to_string(), String::new()),
            ("settings.local.json".to_string(), String::new()),
        ];
        assert!(legacy_hook_referencing_sources(&sources, "hooks/worklist-guard.py").is_empty());
    }
}

#[cfg(test)]
mod audit_ledger_tests {
    use super::{audit_authorization_record, audit_commit_record, audit_record_line};

    #[test]
    fn audit_record_line_is_single_line_stamped_json() {
        let rec = audit_authorization_record(
            "approved",
            &["a".to_string(), "b".to_string()],
            "worklist-action-command",
            true,
        );
        let line = audit_record_line(&rec, 1234);
        assert!(!line.contains('\n'));
        let parsed: serde_json::Value =
            serde_json::from_str(&line).expect("audit line must be valid JSON");
        assert_eq!(parsed["atMs"], 1234);
        assert!(parsed["at"].as_str().is_some_and(|s| !s.is_empty()));
        assert_eq!(parsed["kind"], "authorization");
        assert_eq!(parsed["decision"], "approved");
        assert_eq!(parsed["itemIds"], serde_json::json!(["a", "b"]));
        assert_eq!(parsed["applyAndCommit"], true);
    }

    // audit-ledger-keep-commit-sha-readable: the redactor masks any 40-char
    // hex string, so a record's identifier survives only if its key is on the
    // allowlist. This trap sprang twice — once on `sha`, then on issue-257's
    // `commit` — so the test pins the whole allowlist, not just today's field.
    // issue-index-immediate-refresh: the splice feeds cache_issues_list_row,
    // whose history includes a write that made an empty list sticky, so these
    // pin the shape rather than trusting it.
    // issue-index-immediate-refresh: URL sighting, over the real shape a
    // `gh issue create` tool result carries in the transcript.
    #[test]
    fn issue_numbers_in_tail_finds_created_issue_urls() {
        let tail = r#"{"type":"user","message":{"content":[{"type":"tool_result",
            "content":"https://github.com/judell/bram/issues/260\n"}]}}"#;
        let got = super::issue_numbers_in_tail(tail, "https://github.com/judell/bram");
        assert_eq!(got.len(), 1);
        assert_eq!(got[0].number, 260);
        assert_eq!(
            got[0].comment_id, None,
            "a bare create URL is not a comment sighting"
        );
        assert_eq!(got[0].key(), "260");
    }

    #[test]
    fn issue_numbers_in_tail_dedupes_and_ignores_other_repos() {
        let tail = "https://github.com/judell/bram/issues/7 ... again \
                    https://github.com/judell/bram/issues/7 and \
                    https://github.com/other/repo/issues/99 and \
                    https://github.com/judell/bram/issues/12x";
        let got = super::issue_numbers_in_tail(tail, "https://github.com/judell/bram");
        let nums: Vec<u64> = got.iter().map(|s| s.number).collect();
        assert_eq!(
            nums,
            vec![7, 12],
            "dedupe; foreign repo ignored; digits stop at non-digit"
        );
    }

    // index-issue-comments-on-sighting: `gh issue comment` prints the issue URL
    // with a #issuecomment-<id> fragment. That fragment is what distinguishes
    // "this issue has new content" from "this issue is new", and it is what the
    // seen-set must key on so two comments on one issue are two sightings.
    #[test]
    fn issue_numbers_in_tail_distinguishes_comments_from_creations() {
        let base = "https://github.com/judell/bram";
        let tail = "created https://github.com/judell/bram/issues/264 then \
                    https://github.com/judell/bram/issues/262#issuecomment-5333389524 and \
                    https://github.com/judell/bram/issues/262#issuecomment-5333999999 and \
                    https://github.com/judell/bram/issues/262#issuecomment-5333389524";
        let got = super::issue_numbers_in_tail(tail, base);
        let keys: Vec<String> = got.iter().map(|s| s.key()).collect();
        assert_eq!(
            keys,
            vec!["264", "262#5333389524", "262#5333999999"],
            "creation keys on the number; each distinct comment is its own key; \
             the same comment seen twice collapses"
        );
        assert_eq!(got[0].comment_id, None);
        assert_eq!(got[1].comment_id, Some(5333389524));
    }

    #[test]
    fn issue_sighting_key_separates_comment_from_bare_number() {
        // A creation sighting and a comment sighting on the same issue must not
        // collide, or the first would suppress the second for the process.
        let bare = super::IssueSighting {
            number: 262,
            comment_id: None,
        };
        let commented = super::IssueSighting {
            number: 262,
            comment_id: Some(1),
        };
        assert_ne!(bare.key(), commented.key());
    }

    #[test]
    fn issue_numbers_in_tail_is_inert_without_a_base() {
        assert!(super::issue_numbers_in_tail("issues/1", "").is_empty());
    }

    #[test]
    fn issues_list_upsert_replaces_in_place_and_drops_body() {
        let list = r#"[{"number":9,"title":"nine","state":"OPEN"},{"number":7,"title":"seven","state":"OPEN"}]"#;
        let fresh = serde_json::json!({
            "number": 7, "title": "seven", "state": "CLOSED", "body": "long text"
        });
        let out = super::issues_list_upsert_row(list, &fresh).expect("spliced");
        let rows: Vec<serde_json::Value> = serde_json::from_str(&out).unwrap();
        assert_eq!(rows.len(), 2, "replace, never append a duplicate");
        assert_eq!(rows[0]["number"], 9, "ordering is left alone");
        assert_eq!(rows[1]["state"], "CLOSED", "the row is refreshed in place");
        assert!(
            rows[1].get("body").is_none(),
            "body must not enter the list shape"
        );
    }

    #[test]
    fn issues_list_upsert_inserts_unknown_issue_at_front() {
        let list = r#"[{"number":9,"title":"nine"}]"#;
        let fresh = serde_json::json!({"number": 10, "title": "ten"});
        let out = super::issues_list_upsert_row(list, &fresh).expect("spliced");
        let rows: Vec<serde_json::Value> = serde_json::from_str(&out).unwrap();
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0]["number"], 10);
    }

    // A confident wrong write is the failure mode this cache has already
    // suffered, so an unreadable cache yields None and the caller skips.
    #[test]
    fn issues_list_upsert_refuses_non_array_cache() {
        let fresh = serde_json::json!({"number": 1});
        assert!(super::issues_list_upsert_row("", &fresh).is_none());
        assert!(super::issues_list_upsert_row("{\"oops\":true}", &fresh).is_none());
        assert!(super::issues_list_upsert_row("[]", &serde_json::json!({"no":"number"})).is_none());
    }

    #[test]
    fn audit_record_line_keeps_host_authored_identifiers_readable() {
        let sha = "badfe03f6b9dd240e828e9a518083ff664a0a966";
        let rec = serde_json::json!({
            "kind": "issue-close-fired",
            "issue": 258,
            "commit": sha,
            "sha": sha,
            "branch": "main",
        });
        let parsed: serde_json::Value =
            serde_json::from_str(&audit_record_line(&rec, 1)).expect("valid JSON");
        assert_eq!(parsed["commit"], sha, "commit SHA must stay readable");
        assert_eq!(parsed["sha"], sha);
        assert_eq!(parsed["branch"], "main");
        assert_eq!(parsed["issue"], 258);
        assert_eq!(parsed["kind"], "issue-close-fired");
    }

    // ...and the allowlist must not become a hole: a secret-shaped value in
    // any other field still redacts.
    #[test]
    fn audit_record_line_still_redacts_unlisted_fields() {
        let rec = serde_json::json!({
            "kind": "issue-close-fired",
            "note": "token ghp_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
        });
        let parsed: serde_json::Value =
            serde_json::from_str(&audit_record_line(&rec, 1)).expect("valid JSON");
        let note = parsed["note"].as_str().unwrap_or_default();
        assert!(
            !note.contains("ghp_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"),
            "unlisted field must still redact, got: {note}"
        );
    }

    #[test]
    fn audit_commit_record_shape() {
        // A real 40-hex-char SHA: the redactor's token patterns match
        // this shape, and the first live commit record masked its own
        // sha (audit-ledger-preserve-sha). The exempt field must
        // survive audit_record_line intact.
        let sha = "3e28389ac4bd2d6b8666aa78a849b471cd17ef58";
        let rec = audit_commit_record(
            sha,
            "main",
            &["x".to_string()],
            &["app/a.js".to_string()],
            "apply-and-commit",
        );
        let line = audit_record_line(&rec, 5678);
        let parsed: serde_json::Value =
            serde_json::from_str(&line).expect("audit line must be valid JSON");
        assert_eq!(parsed["kind"], "commit");
        assert_eq!(parsed["sha"], sha);
        assert_eq!(parsed["branch"], "main");
        assert_eq!(parsed["itemIds"], serde_json::json!(["x"]));
        assert_eq!(parsed["stagedPaths"], serde_json::json!(["app/a.js"]));
        assert_eq!(parsed["authorization"], "apply-and-commit");
        assert_eq!(parsed["atMs"], 5678);
    }

    #[test]
    fn audit_record_line_redacts_credentials() {
        let secret = format!("sk-ant-{}", "a".repeat(90));
        let rec = serde_json::json!({
            "kind": "authorization",
            "decision": "approved",
            "source": secret,
        });
        let line = audit_record_line(&rec, 42);
        assert!(!line.contains(&secret));
    }
}

#[cfg(test)]
mod answer_binding_tests {
    use super::choose_answer_binding_id;

    // The 2026-08-08 05:23:45 churn specimen: a hook-claimed Bash prompt
    // (own id) answered while the pending-call lookup returns the
    // still-running Agent dispatch. The displayed claim's id must win.
    #[test]
    fn displayed_claim_id_wins_over_stale_pending_call() {
        let (id, src) = choose_answer_binding_id(
            Some("toolu_01LAokoVfLG6HB36dZofVJpX".to_string()),
            Some("toolu_013PiPf8VNgHcFeNCT7j5KDZ".to_string()),
            Some("Agent(general-purpose: implement the thing)"),
            "Bash",
        );
        assert_eq!(id.as_deref(), Some("toolu_01LAokoVfLG6HB36dZofVJpX"));
        assert_eq!(src, "displayed-claim");
    }

    // A claimless Bash prompt while the oldest unresolved call is the
    // Agent dispatch: binding nothing (stash for clear-time binding)
    // beats binding the wrong id.
    #[test]
    fn claimless_prompt_rejects_mismatched_pending_call() {
        let (id, src) = choose_answer_binding_id(
            None,
            Some("toolu_013PiPf8VNgHcFeNCT7j5KDZ".to_string()),
            Some("Agent(general-purpose: implement the thing)"),
            "Bash",
        );
        assert_eq!(id, None);
        assert_eq!(src, "pending-call-tool-mismatch");
    }

    // The record-flush-lag case the pending-call preference existed
    // for: a claimless Bash prompt whose pending call IS the Bash call.
    #[test]
    fn claimless_prompt_keeps_matching_pending_call() {
        let (id, src) = choose_answer_binding_id(
            None,
            Some("toolu_bash".to_string()),
            Some("Bash(jq -r '.x' file.json)"),
            "Bash",
        );
        assert_eq!(id.as_deref(), Some("toolu_bash"));
        assert_eq!(src, "pending-call");
    }

    // No signature at all: the pending call's tool cannot be confirmed,
    // so it must not bind.
    #[test]
    fn claimless_prompt_rejects_unverifiable_pending_call() {
        let (id, src) = choose_answer_binding_id(None, Some("toolu_x".to_string()), None, "Bash");
        assert_eq!(id, None);
        assert_eq!(src, "pending-call-tool-mismatch");
    }

    #[test]
    fn nothing_available_binds_nothing() {
        let (id, src) = choose_answer_binding_id(None, None, None, "Bash");
        assert_eq!(id, None);
        assert_eq!(src, "none");
    }
}

#[cfg(test)]
mod dismiss_suppressor_gate_tests {
    use super::dismiss_suppressor_gate;

    // Should suppress: the 2026-08-08 17:05 ghost — armed for Read with
    // fingerprint F, stale pixels re-detected as Bash with fingerprint F.
    #[test]
    fn identical_fingerprint_engages_across_tools() {
        assert_eq!(
            dismiss_suppressor_gate(false, Some("exact")),
            "engage-cross-tool"
        );
    }

    // Should suppress: the ordinary same-tool re-detect, unchanged.
    #[test]
    fn identical_fingerprint_same_tool_engages() {
        assert_eq!(dismiss_suppressor_gate(true, Some("exact")), "engage");
    }

    // A mid-paint prefix match takes the same suppression path; the match
    // kind remains explicit for trace and gate tests.
    #[test]
    fn prefix_fingerprint_engages() {
        assert_eq!(dismiss_suppressor_gate(true, Some("prefix")), "engage");
        assert_eq!(
            dismiss_suppressor_gate(false, Some("prefix")),
            "engage-cross-tool"
        );
    }

    // Should NOT suppress: same tool, different labels — the #193
    // genuinely-new-menu class the labels gate was built for.
    #[test]
    fn different_fingerprint_same_tool_shows() {
        assert_eq!(dismiss_suppressor_gate(true, None), "fingerprint-mismatch");
    }

    // Should NOT suppress: different tool AND different labels — a fully
    // unrelated prompt, exactly what the old tool gate protected.
    #[test]
    fn unrelated_prompt_passes() {
        assert_eq!(dismiss_suppressor_gate(false, None), "pass");
    }
}

#[cfg(test)]
mod describe_error_retryable_tests {
    use super::describe_error_retryable;

    #[test]
    fn persistent_statuses_do_not_retry() {
        // Billing 400 (the 2026-08-10 credit-less-key storm), bad key 401,
        // forbidden 403.
        assert!(!describe_error_retryable(400));
        assert!(!describe_error_retryable(401));
        assert!(!describe_error_retryable(403));
    }

    #[test]
    fn transient_statuses_keep_retrying() {
        for s in [408, 409, 429, 500, 502, 503, 529] {
            assert!(describe_error_retryable(s), "status {} should retry", s);
        }
    }
}

#[cfg(test)]
mod describe_cache_tests {
    use super::{
        build_describe_prompt, cap_chars_head, cap_chars_tail, describe_cache_connection,
        describe_cache_key, describe_cache_key_for_version, DescribeCache,
        DESCRIBE_COMMAND_MAX_CHARS, DESCRIBE_CONTEXT_MAX_CHARS, DESCRIBE_EXISTING_MAX_CHARS,
        DESCRIBE_PROMPT_SCHEMA_VERSION, DESCRIBE_RESULT_MAX_CHARS, DESCRIBE_TOOL_NAME_MAX_CHARS,
    };
    use std::path::{Path, PathBuf};
    use std::sync::atomic::{AtomicUsize, Ordering};

    static NEXT_DB: AtomicUsize = AtomicUsize::new(0);

    struct TempDb(PathBuf);

    impl TempDb {
        fn new(label: &str) -> Self {
            let n = NEXT_DB.fetch_add(1, Ordering::SeqCst);
            Self(std::env::temp_dir().join(format!(
                "bram-describe-cache-{}-{}-{}.db",
                label,
                std::process::id(),
                n
            )))
        }

        fn path(&self) -> &Path {
            &self.0
        }
    }

    impl Drop for TempDb {
        fn drop(&mut self) {
            let _ = std::fs::remove_file(&self.0);
            let _ = std::fs::remove_file(format!("{}-wal", self.0.display()));
            let _ = std::fs::remove_file(format!("{}-shm", self.0.display()));
        }
    }

    #[test]
    fn caps_are_unicode_safe_and_prompt_stays_bounded() {
        assert_eq!(cap_chars_head("a🦀bc", 3), "a🦀b");
        assert_eq!(cap_chars_tail("a🦀bc", 3), "🦀bc");

        let long = "x".repeat(10_000);
        let tool = cap_chars_head(&long, DESCRIBE_TOOL_NAME_MAX_CHARS);
        let command = cap_chars_head(&long, DESCRIBE_COMMAND_MAX_CHARS);
        let existing = cap_chars_head(&long, DESCRIBE_EXISTING_MAX_CHARS);
        let context = cap_chars_tail(&long, DESCRIBE_CONTEXT_MAX_CHARS);
        let result = cap_chars_head(&long, DESCRIBE_RESULT_MAX_CHARS);
        assert_eq!(tool.chars().count(), DESCRIBE_TOOL_NAME_MAX_CHARS);
        assert_eq!(command.chars().count(), DESCRIBE_COMMAND_MAX_CHARS);
        assert_eq!(existing.chars().count(), DESCRIBE_EXISTING_MAX_CHARS);
        assert_eq!(context.chars().count(), DESCRIBE_CONTEXT_MAX_CHARS);
        assert_eq!(result.chars().count(), DESCRIBE_RESULT_MAX_CHARS);

        let prompt = build_describe_prompt(&tool, &command, &existing, &context, &result);
        assert!(
            prompt.chars().count() < 4_096,
            "maximal ASCII prompt should remain below 4,096 characters"
        );
    }

    #[test]
    fn cache_key_covers_every_prompt_input_model_and_schema() {
        let base = describe_cache_key_for_version(1, "model", "tool", "cmd", "desc", "ctx", "out");
        for changed in [
            describe_cache_key_for_version(2, "model", "tool", "cmd", "desc", "ctx", "out"),
            describe_cache_key_for_version(1, "other", "tool", "cmd", "desc", "ctx", "out"),
            describe_cache_key_for_version(1, "model", "other", "cmd", "desc", "ctx", "out"),
            describe_cache_key_for_version(1, "model", "tool", "other", "desc", "ctx", "out"),
            describe_cache_key_for_version(1, "model", "tool", "cmd", "other", "ctx", "out"),
            describe_cache_key_for_version(1, "model", "tool", "cmd", "desc", "other", "out"),
            describe_cache_key_for_version(1, "model", "tool", "cmd", "desc", "ctx", "other"),
        ] {
            assert_ne!(base, changed);
        }
        assert_eq!(base.len(), 32);
        assert_eq!(
            describe_cache_key_for_version(1, "model", "tool", "cmd", "desc", "ctx", "out"),
            base
        );
    }

    #[test]
    fn sqlite_round_trip_persists_only_opaque_identity_and_description() {
        let db = TempDb::new("round-trip");
        let model = "claude-haiku-4-5";
        let raw_material = "TOP_SECRET_COMMAND_MATERIAL";
        let key = describe_cache_key(model, "Bash", raw_material, "", "", "");
        let mut cache = DescribeCache::empty(db.path().to_path_buf(), model);
        cache.record("tool-1", &key, "Inspect the cache behavior");
        cache.persist_entry("tool-1").expect("persist entry");

        let loaded = DescribeCache::load(db.path().to_path_buf(), model).expect("reload cache");
        assert_eq!(
            loaded.by_id.get("tool-1"),
            Some(&(key.clone(), "Inspect the cache behavior".to_string()))
        );
        assert_eq!(
            loaded.by_key.get(&key).map(String::as_str),
            Some("Inspect the cache behavior")
        );

        let conn = describe_cache_connection(db.path()).expect("open cache db");
        let stored: String = conn
            .query_row(
                "SELECT model || id || request_key || description FROM tool_descriptions",
                [],
                |row| row.get(0),
            )
            .expect("read stored fields");
        assert!(!stored.contains(raw_material));
        assert!(stored.contains(&key));
    }

    #[test]
    fn model_and_prompt_schema_changes_invalidate_rows() {
        let db = TempDb::new("invalidate");
        let mut cache = DescribeCache::empty(db.path().to_path_buf(), "model-a");
        cache.record("tool-1", "opaque-key", "A description");
        cache.persist_entry("tool-1").expect("persist model A");

        let model_b = DescribeCache::load(db.path().to_path_buf(), "model-b").expect("load B");
        assert!(model_b.records.is_empty());

        let conn = describe_cache_connection(db.path()).expect("open cache db");
        conn.execute(
            "INSERT INTO tool_descriptions \
               (model, prompt_schema_version, id, request_key, description, touched_at_ms) \
             VALUES (?1, ?2, 'old-schema', 'old-key', 'old description', 1)",
            rusqlite::params!["model-b", i64::from(DESCRIBE_PROMPT_SCHEMA_VERSION) + 1],
        )
        .expect("insert stale prompt row");
        drop(conn);
        let reloaded = DescribeCache::load(db.path().to_path_buf(), "model-b").expect("reload B");
        assert!(reloaded.records.is_empty());
    }

    #[test]
    fn oldest_entries_are_evicted_at_the_bound() {
        let db = TempDb::new("evict");
        let mut cache = DescribeCache::empty(db.path().to_path_buf(), "model");
        cache.record_with_limit("old", "k1", "one", 1, 2);
        cache
            .persist_entry_with_limit("old", 2)
            .expect("persist old");
        cache.record_with_limit("middle", "k2", "two", 2, 2);
        cache
            .persist_entry_with_limit("middle", 2)
            .expect("persist middle");
        cache.record_with_limit("new", "k3", "three", 3, 2);
        cache
            .persist_entry_with_limit("new", 2)
            .expect("persist new");
        assert!(!cache.records.contains_key("old"));
        assert!(cache.records.contains_key("middle"));
        assert!(cache.records.contains_key("new"));
        let loaded = DescribeCache::load(db.path().to_path_buf(), "model").expect("reload cache");
        assert!(!loaded.records.contains_key("old"));
        assert!(loaded.records.contains_key("middle"));
        assert!(loaded.records.contains_key("new"));
    }
}

#[cfg(test)]
mod describe_frontier_js_tests {
    #[test]
    fn historical_baseline_is_quiet_and_new_rows_queue_once() {
        let helpers = include_str!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../app/__shell/helpers.js"
        ));
        let start_marker = "window.__bramCollectNewDescribeRows = function";
        let end_marker = "\n};\n\nfunction __bramEagerDescribe";
        let start = helpers.find(start_marker).expect("frontier helper start");
        let tail = &helpers[start..];
        let end = tail.find(end_marker).expect("frontier helper end") + 3;

        let mut script = String::from(
            "global.window = {\n\
               __bramDescribeMaterial: function (e) { return e.material || ''; },\n\
               __bramDescribeRequested: {}\n\
             };\n",
        );
        script.push_str(&tail[..end]);
        script.push_str(
            r#"
function tool(id, material, aiDescription) {
  return { kind: 'tool', id: id, material: material || '', aiDescription: aiDescription || '' };
}
function payload(sid, rows, windowStart) {
  var p = { sid: sid, turns: [{ entries: rows }] };
  if (windowStart !== undefined) p.windowStart = windowStart;
  return p;
}
function ok(value, message) { if (!value) throw new Error(message); }
var state = { stream: '', initialized: false, complete: false, seen: {} };
var first = window.__bramCollectNewDescribeRows(payload('s1', [tool('old-a', 'a'), tool('old-b', 'b')], 0), state, 's1');
ok(first.baseline && first.queue.length === 0, 'initial history must be a quiet baseline');
var appended = window.__bramCollectNewDescribeRows(payload('s1', [tool('old-a', 'a'), tool('old-b', 'b'), tool('new-c', 'c')], 0), state, 's1');
ok(!appended.baseline && appended.queue.length === 1 && appended.queue[0].id === 'new-c', 'one appended row must queue');
var repeated = window.__bramCollectNewDescribeRows(payload('s1', [tool('old-a', 'a'), tool('old-b', 'b'), tool('new-c', 'c')], 0), state, 's1');
ok(repeated.queue.length === 0, 'rebroadcast must not queue twice');
var cached = window.__bramCollectNewDescribeRows(payload('s1', [tool('cached-d', 'd', 'cached')], 0), state, 's1');
ok(cached.queue.length === 0, 'overlay-described row must stay quiet');
var pending = window.__bramCollectNewDescribeRows(payload('s1', [tool('streaming-e', '')], 0), state, 's1');
ok(pending.queue.length === 0, 'material-less row must wait');
var ready = window.__bramCollectNewDescribeRows(payload('s1', [tool('streaming-e', 'e')], 0), state, 's1');
ok(ready.queue.length === 1, 'streaming row must queue when material arrives');
var rotated = window.__bramCollectNewDescribeRows(payload('s2', [tool('old-z', 'z')], 0), state, 's2');
ok(rotated.baseline && rotated.queue.length === 0, 'session rotation must establish a new baseline');
var windowed = { stream: '', initialized: false, complete: false, seen: {} };
ok(window.__bramCollectNewDescribeRows(payload('s3', [tool('tail', 't')], 8), windowed, 's3').queue.length === 0, 'initial suffix must be baseline');
ok(window.__bramCollectNewDescribeRows(payload('s3', [tool('tail', 't'), tool('arrived-before-prefix', 'n')], 8), windowed, 's3').queue.length === 0, 'frontier stays quiet until prefix arrives');
ok(window.__bramCollectNewDescribeRows(payload('s3', [tool('historic-prefix', 'h'), tool('tail', 't'), tool('arrived-before-prefix', 'n')], 0), windowed, 's3').queue.length === 0, 'revealed prefix is historical');
ok(window.__bramCollectNewDescribeRows(payload('s3', [tool('historic-prefix', 'h'), tool('tail', 't'), tool('arrived-before-prefix', 'n'), tool('after-frontier', 'x')], 0), windowed, 's3').queue.length === 1, 'post-frontier row queues');
"#,
        );
        let output = std::process::Command::new("node")
            .arg("-e")
            .arg(script)
            .output()
            .expect("node is required by the Bram frontend toolchain");
        assert!(
            output.status.success(),
            "frontier JS test failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }
}

#[cfg(test)]
mod menu_labels_match_tests {
    use super::{grid_menu_dismissed_label_match, menu_labels_match};

    fn labels(v: &[&str]) -> Vec<String> {
        v.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn identical_sets_match_exact() {
        let a = labels(&["Yes", "Yes, and don't ask again for: sysctl *", "No"]);
        assert_eq!(menu_labels_match(&a, &a.clone()), Some("exact"));
    }

    // 2026-08-08 19:27:37 specimen: option 2 captured mid-word as "ye".
    #[test]
    fn cut_label_matches_as_prefix() {
        let armed = labels(&[
            "Yes",
            "Yes, and don't ask again for: system_profiler SPHardwareDataType *",
            "No",
        ]);
        let captured = labels(&["Yes", "Ye", "No"]);
        assert_eq!(menu_labels_match(&armed, &captured), Some("prefix"));
    }

    // 19:27:38 specimen: label cut exactly at the grant scope.
    #[test]
    fn scope_truncated_label_matches_as_prefix() {
        let armed = labels(&[
            "Yes",
            "Yes, and don't ask again for: system_profiler SPHardwareDataType *",
            "No",
        ]);
        let captured = labels(&["Yes", "Yes, and don't ask again for: ", "No"]);
        assert_eq!(menu_labels_match(&armed, &captured), Some("prefix"));
    }

    // 19:37:26 specimen: a 3-option menu captured with 2 options.
    #[test]
    fn missing_trailing_option_matches_as_prefix() {
        let armed = labels(&[
            "Yes",
            "Yes, and always allow access to Downloads/ from this project",
            "No",
        ]);
        let captured = labels(&[
            "Yes",
            "Yes, and always allow access to Downloads/ from this project",
        ]);
        assert_eq!(menu_labels_match(&armed, &captured), Some("prefix"));
    }

    // The armed side may be the truncated one — it too comes from a grid
    // sighting.
    #[test]
    fn truncated_armed_side_also_matches() {
        let armed = labels(&["Yes", "Ye"]);
        let captured = labels(&["Yes", "Yes, and don't ask again for: sysctl *", "No"]);
        assert_eq!(menu_labels_match(&armed, &captured), Some("prefix"));
    }

    // The grid-rescue anti-ghost gate must use the same tolerant match; this
    // is the call site that prevents answered-claim rescue churn.
    #[test]
    fn grid_dismissed_gate_accepts_normalized_truncated_repaint() {
        let dismissed = labels(&[
            "Yes",
            "Yes, and don't ask again for: system_profiler SPHardwareDataType *",
            "No",
        ]);
        let grid = labels(&["yes", "ye"]);

        assert_eq!(
            grid_menu_dismissed_label_match(&dismissed, &grid),
            Some("prefix")
        );
    }

    // A genuinely different same-shape menu diverges inside option 2's
    // scope text — must NOT merge.
    #[test]
    fn different_command_scope_does_not_match() {
        let armed = labels(&[
            "Yes",
            "Yes, and don't ask again for: system_profiler SPHardwareDataType *",
            "No",
        ]);
        let captured = labels(&["Yes", "Yes, and don't ask again for: sysctl *", "No"]);
        assert_eq!(menu_labels_match(&armed, &captured), None);
    }

    #[test]
    fn unrelated_and_empty_sets_do_not_match() {
        let armed = labels(&["Yes", "No"]);
        assert_eq!(
            menu_labels_match(&armed, &labels(&["Review hooks", "Trust all"])),
            None
        );
        assert_eq!(menu_labels_match(&armed, &labels(&[])), None);
        assert_eq!(menu_labels_match(&labels(&[]), &armed), None);
        // An empty captured label must not prefix-match everything.
        assert_eq!(menu_labels_match(&armed, &labels(&["Yes", ""])), None);
        assert_eq!(
            menu_labels_match(&labels(&["Yes", ""]), &labels(&["Yes", ""])),
            None
        );
        assert_eq!(
            menu_labels_match(&labels(&["Yes", " "]), &labels(&["Yes", "No"])),
            None
        );
    }
}

#[cfg(test)]
mod issues_list_cache_tests {
    use super::{cache_issues_list_row, issues_list_stale};
    use crate::search_index;

    fn mem_conn() -> rusqlite::Connection {
        search_index::open(":memory:").expect("in-memory index")
    }

    fn insert_issue_doc(conn: &rusqlite::Connection) {
        let row = search_index::IndexRow {
            kind: "issue".to_string(),
            source: String::new(),
            date: "1".to_string(),
            link: String::new(),
            content: "an issue".to_string(),
            intent: String::new(),
            file: "issue:1".to_string(),
            tool_ids: None,
            extra: String::new(),
        };
        search_index::index_doc(conn, &row, 1, 0).expect("index issue doc");
    }

    // The 2026-08-08 poison shape: an empty list arriving while issue docs
    // exist must be refused and flagged stale, leaving any prior row alone.
    #[test]
    fn empty_list_with_issue_docs_is_refused_and_marked_stale() {
        let conn = mem_conn();
        insert_issue_doc(&conn);
        assert_eq!(cache_issues_list_row(&conn, "[3 real issues]"), "cached");
        assert_eq!(cache_issues_list_row(&conn, "[]"), "empty-contradiction");
        assert_eq!(
            search_index::get_extra(&conn, "issues:list")
                .unwrap()
                .as_deref(),
            Some("[3 real issues]"),
            "prior good row must keep serving"
        );
        assert!(issues_list_stale(&conn), "stale marker must arm the retry");
    }

    // A genuinely issueless repo still caches [] normally.
    #[test]
    fn empty_list_without_issue_docs_caches_normally() {
        let conn = mem_conn();
        assert_eq!(cache_issues_list_row(&conn, "[]"), "cached");
        assert_eq!(
            search_index::get_extra(&conn, "issues:list")
                .unwrap()
                .as_deref(),
            Some("[]")
        );
        assert!(!issues_list_stale(&conn));
    }

    // A successful non-empty rebuild clears a pending stale marker.
    #[test]
    fn good_list_clears_stale_marker() {
        let conn = mem_conn();
        insert_issue_doc(&conn);
        assert_eq!(cache_issues_list_row(&conn, "[]"), "empty-contradiction");
        assert!(issues_list_stale(&conn));
        assert_eq!(cache_issues_list_row(&conn, "[1 issue]"), "cached");
        assert!(!issues_list_stale(&conn));
    }
}

