#[cfg(test)]
mod menu_prompt_identity_transport_tests {
    use super::{bind_menu_prompt_id, PtyMenu, TurnState};

    #[test]
    fn one_bound_menu_serializes_identity_on_both_pane_transports() {
        let mut menu = Some(PtyMenu {
            tool: "Bash".to_string(),
            text: "Apply proposed file edits".to_string(),
            ..PtyMenu::default()
        });
        bind_menu_prompt_id(&mut menu, Some("p-live"));

        // `pty-menu-changed` serializes the menu directly.
        let direct = serde_json::to_value(&menu).expect("direct menu payload");
        assert_eq!(direct["promptId"], "p-live");

        // `turn-state-changed` and `/__turn-state` serialize the same menu
        // nested under pendingMenu. The identity must not depend on which
        // event wins the iframe's millisecond stale-event arbitration.
        let mut turn_state = TurnState::idle();
        turn_state.pending_menu = menu;
        let nested = serde_json::to_value(&turn_state).expect("turn-state payload");
        assert_eq!(nested["pendingMenu"]["promptId"], "p-live");
    }
}

// POST /__describe-command {id, command, description?} — synthesize (or
// upgrade) a one-line intent header for a tool expansion via the
// Anthropic Messages API (haiku-command-descriptions). Opt-in twice
// over: the .bram.json `ai.describeCommands` flag must be true AND
// ANTHROPIC_API_KEY must be present in the host environment (the key is
// never stored in .bram.json — it's a tracked file). When an
// agent-authored description rides along, the prompt asks the model to
// keep it if accurate and upgrade it if warranted (approval feedback on
// haiku-command-descriptions). Synchronous by design: handle_http runs
// each request on its own thread, and the iframe caller awaits the
// response to trigger its /__turns refetch — a describe completion
// doesn't change the session file, so the slim tick's zero-delta
// suppression would swallow a host-side signal.
// describe-latch-persistent-api-errors: classify an upstream describe
// failure as retryable. Persistent conditions (bad request / billing 400,
// auth 401, forbidden 403) will not recover within a session, so the client
// latches and stops the eager-scan re-POST storm (3,704 identical 400s in
// one session on a credit-less key, 2026-08-10). Transient conditions
// (408, 409, 429, all 5xx, and the non-HTTP transport/parse/empty one-offs)
// may recover, so the client keeps retrying. A manual tool-row expand
// bypasses the latch regardless, so a fixed key revives without relaunch.
fn describe_error_retryable(status: u16) -> bool {
    !matches!(status, 400 | 401 | 403)
}

fn handle_describe_command<R: tauri::Runtime>(
    app: &AppHandle<R>,
    body: &[u8],
) -> (u16, &'static str, Vec<u8>) {
    const JSON: &str = "application/json; charset=utf-8";
    // describe-backfill-observability: server-side view of backfill
    // pressure. Guard decrements on every return path.
    static DESCRIBE_INFLIGHT: std::sync::atomic::AtomicUsize =
        std::sync::atomic::AtomicUsize::new(0);
    struct InflightGuard;
    impl Drop for InflightGuard {
        fn drop(&mut self) {
            DESCRIBE_INFLIGHT.fetch_sub(1, std::sync::atomic::Ordering::SeqCst);
        }
    }
    let describe_concurrent =
        DESCRIBE_INFLIGHT.fetch_add(1, std::sync::atomic::Ordering::SeqCst) + 1;
    let _inflight_guard = InflightGuard;
    let parsed: serde_json::Value = match serde_json::from_slice(body) {
        Ok(v) => v,
        Err(e) => {
            return (
                400,
                JSON,
                serde_json::json!({ "ok": false, "reason": format!("bad json: {}", e) })
                    .to_string()
                    .into_bytes(),
            )
        }
    };
    let id = parsed.get("id").and_then(|v| v.as_str()).unwrap_or("");
    let command_raw = parsed.get("command").and_then(|v| v.as_str()).unwrap_or("");
    let existing_raw = parsed
        .get("description")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim();
    if id.is_empty() || command_raw.trim().is_empty() {
        return (
            400,
            JSON,
            br#"{"ok":false,"reason":"id and command required"}"#.to_vec(),
        );
    }
    let config = project_root(Some(app)).and_then(|root| load_project_config(&root));
    // Default OFF. Presence of ANTHROPIC_API_KEY alone is not consent to
    // send project material to an external model.
    let enabled = project_config_describe_commands(config.clone());
    if !enabled {
        append_bram_trace_line(
            app,
            "ai-describe",
            &format!("op=skip reason=disabled id={}", id),
        );
        return (200, JSON, br#"{"ok":false,"reason":"disabled"}"#.to_vec());
    }
    let model = describe_model(config.as_ref());
    // Optional context riders (iterate 2026-07-08 "what could we send to
    // make best use of it"): the tool name, the agent's prose immediately
    // before the call (its stated intent — the highest-signal input), and
    // the head of the command's output. The host owns the authoritative
    // budget so every caller gets the same bounded, char-boundary-safe
    // prompt. Context keeps its TAIL (the sentence nearest the call);
    // every other field keeps its HEAD.
    let tool_name_raw = parsed
        .get("name")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim();
    let context_raw = parsed
        .get("context")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim();
    let result_raw = parsed
        .get("result")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim();
    let (command_redacted, command_redactions) = redact_sensitive_text(command_raw.trim());
    let (existing_redacted, existing_redactions) = redact_sensitive_text(existing_raw);
    let (tool_name_redacted, tool_name_redactions) = redact_sensitive_text(tool_name_raw);
    let (context_redacted, context_redactions) = redact_sensitive_text(context_raw);
    let (result_redacted, result_redactions) = redact_sensitive_text(result_raw);
    // Re-cap after redaction because a replacement marker can be longer than
    // the matched secret. These are the exact fields hashed and sent.
    let command = cap_chars_head(&command_redacted, DESCRIBE_COMMAND_MAX_CHARS);
    let existing = cap_chars_head(&existing_redacted, DESCRIBE_EXISTING_MAX_CHARS);
    let tool_name = cap_chars_head(&tool_name_redacted, DESCRIBE_TOOL_NAME_MAX_CHARS);
    let context = cap_chars_tail(&context_redacted, DESCRIBE_CONTEXT_MAX_CHARS);
    let result_head = cap_chars_head(&result_redacted, DESCRIBE_RESULT_MAX_CHARS);
    let redactions = command_redactions
        + existing_redactions
        + tool_name_redactions
        + context_redactions
        + result_redactions;
    // Both lookup paths require the complete effective prompt identity.
    // The key includes model and prompt schema as well as every bounded,
    // redacted field, so neither a reused id nor a repeated command can
    // return a description generated for different inputs.
    let cache_key = describe_cache_key(
        &model,
        &tool_name,
        &command,
        &existing,
        &context,
        &result_head,
    );
    {
        let mut guard = match describe_cache_guard(app, &model) {
            Ok(guard) => guard,
            Err(reason) => {
                append_bram_trace_line(
                    app,
                    "ai-describe",
                    &format!("op=error status=cache id={} detail={}", id, reason),
                );
                return (500, JSON, br#"{"ok":false,"reason":"cache"}"#.to_vec());
            }
        };
        let cache = guard.as_mut().expect("describe cache initialized");
        let id_hit = cache.by_id.get(id).and_then(|(stored_key, description)| {
            (stored_key == &cache_key).then(|| description.clone())
        });
        let mut refresh_ids = Vec::new();
        let (hit, source) = if let Some(description) = id_hit {
            (Some(description), "id")
        } else if let Some(description) = cache.by_key.get(&cache_key).cloned() {
            let evicted = cache.record(id, &cache_key, &description);
            if let Err(error) = cache.persist_entry(id) {
                append_bram_trace_line(
                    app,
                    "ai-describe",
                    &format!("op=cache-write-error id={} detail={}", id, error),
                );
            }
            refresh_ids.push(id.to_string());
            refresh_ids.extend(evicted);
            (Some(description), "key")
        } else {
            (None, "")
        };
        if let Some(desc) = hit {
            if !refresh_ids.is_empty() {
                let hint = projected_session_path_for_tool(id);
                queue_search_intent_refresh(&refresh_ids, hint, false);
            }
            append_bram_trace_line(
                app,
                "ai-describe",
                &format!("op=hit source={} model={} id={}", source, model, id),
            );
            let body = serde_json::json!({ "ok": true, "description": desc, "cached": true });
            return (200, JSON, body.to_string().into_bytes());
        }
    }
    let key = std::env::var("ANTHROPIC_API_KEY").unwrap_or_default();
    if key.trim().is_empty() {
        append_bram_trace_line(
            app,
            "ai-describe",
            &format!("op=skip reason=no-key id={}", id),
        );
        return (200, JSON, br#"{"ok":false,"reason":"no-key"}"#.to_vec());
    }
    // Prompt shape grown from the 2026-07-08 Haiku feasibility test (12
    // real Codex exec_command samples, 11/12 shippable on command text
    // alone) plus the context riders above: the agent's stated intent
    // beats a mechanical paraphrase of the command, and the result head
    // disambiguates what actually happened. The upgrade variant carries
    // the agent-authored sentence and asks for it back unchanged when
    // it's already good.
    // describe-edit-write-rows / describe-read-rows: the payload may be a
    // shell command, a file diff/patch, written content, or a file/search
    // target (Read/Grep/Glob) — say so, so Haiku doesn't describe a diff
    // or a path as a command.
    let prompt = build_describe_prompt(&tool_name, &command, &existing, &context, &result_head);
    let prompt_chars = prompt.chars().count();
    let command_chars = command.chars().count();
    let tool_chars = tool_name.chars().count();
    let existing_chars = existing.chars().count();
    let context_chars = context.chars().count();
    let result_chars = result_head.chars().count();
    let req_body = serde_json::json!({
        "model": model,
        "max_tokens": 100,
        "messages": [{ "role": "user", "content": prompt }],
    });
    let started = std::time::Instant::now();
    let resp = ureq::post("https://api.anthropic.com/v1/messages")
        .set("x-api-key", &key)
        .set("anthropic-version", "2023-06-01")
        .set("content-type", "application/json")
        .send_string(&req_body.to_string());
    let ms = started.elapsed().as_millis();
    let resp = match resp {
        Ok(r) => r,
        Err(ureq::Error::Status(code, r)) => {
            let detail = r.into_string().unwrap_or_default();
            let detail_line = detail
                .split('\n')
                .next()
                .unwrap_or("")
                .chars()
                .take(200)
                .collect::<String>();
            append_bram_trace_line(
                app,
                "ai-describe",
                &format!(
                    "op=error status={} ms={} id={} detail={}",
                    code, ms, id, detail_line
                ),
            );
            let body = serde_json::json!({
                "ok": false,
                "reason": format!("api status {}", code),
                "retryable": describe_error_retryable(code),
            });
            return (502, JSON, body.to_string().into_bytes());
        }
        Err(e) => {
            append_bram_trace_line(
                app,
                "ai-describe",
                &format!("op=error status=transport ms={} id={} detail={}", ms, id, e),
            );
            return (
                502,
                JSON,
                br#"{"ok":false,"reason":"transport","retryable":true}"#.to_vec(),
            );
        }
    };
    let payload: serde_json::Value = match resp
        .into_string()
        .ok()
        .and_then(|s| serde_json::from_str(&s).ok())
    {
        Some(v) => v,
        None => {
            append_bram_trace_line(
                app,
                "ai-describe",
                &format!("op=error status=parse ms={} id={}", ms, id),
            );
            return (
                502,
                JSON,
                br#"{"ok":false,"reason":"parse","retryable":true}"#.to_vec(),
            );
        }
    };
    let desc = payload
        .get("content")
        .and_then(|c| c.as_array())
        .and_then(|a| {
            a.iter()
                .find(|b| b.get("type").and_then(|t| t.as_str()) == Some("text"))
        })
        .and_then(|b| b.get("text"))
        .and_then(|t| t.as_str())
        .unwrap_or("")
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ");
    if desc.is_empty() {
        append_bram_trace_line(
            app,
            "ai-describe",
            &format!("op=error status=empty ms={} id={}", ms, id),
        );
        return (
            502,
            JSON,
            br#"{"ok":false,"reason":"empty","retryable":true}"#.to_vec(),
        );
    }
    let input_tokens = payload
        .get("usage")
        .and_then(|u| u.get("input_tokens"))
        .and_then(|v| v.as_u64())
        .unwrap_or(0);
    let output_tokens = payload
        .get("usage")
        .and_then(|u| u.get("output_tokens"))
        .and_then(|v| v.as_u64())
        .unwrap_or(0);
    let cache_write_tokens = payload
        .get("usage")
        .and_then(|u| u.get("cache_creation_input_tokens"))
        .and_then(|v| v.as_u64())
        .unwrap_or(0);
    let cache_read_tokens = payload
        .get("usage")
        .and_then(|u| u.get("cache_read_input_tokens"))
        .and_then(|v| v.as_u64())
        .unwrap_or(0);
    let mut refresh_ids = Vec::new();
    match describe_cache_guard(app, &model) {
        Ok(mut guard) => {
            let cache = guard.as_mut().expect("describe cache initialized");
            let evicted = cache.record(id, &cache_key, &desc);
            if let Err(error) = cache.persist_entry(id) {
                append_bram_trace_line(
                    app,
                    "ai-describe",
                    &format!("op=cache-write-error id={} detail={}", id, error),
                );
            }
            refresh_ids.push(id.to_string());
            refresh_ids.extend(evicted);
        }
        Err(error) => append_bram_trace_line(
            app,
            "ai-describe",
            &format!("op=cache-write-error id={} detail={}", id, error),
        ),
    }
    if !refresh_ids.is_empty() {
        let hint = projected_session_path_for_tool(id);
        queue_search_intent_refresh(&refresh_ids, hint, false);
    }
    // Main-view refresh is caller-driven (helpers.js awaits this response
    // and refetches /__turns). Subagent views refetch on subagents-changed,
    // which nothing else fires for a finished agent — nudge it here so a
    // described row in a subagent transcript re-renders too.
    emit_replayable_signal(app, "subagents-changed");
    // Reduction baseline captured before this cache/frontier shipped:
    // Anthropic's 2026-08-01..14 Haiku chart showed ~49M total tokens; a
    // 2026-08-14 20:25:57Z..20:53:00Z local backfill window made 73 calls,
    // 34,769 input + 1,166 output tokens (input p50=382, p95=1,413,
    // max=1,639). The content-free size/cache fields below make the same
    // distribution and avoided API-cache behavior measurable after restart.
    append_bram_trace_line(
        app,
        "ai-describe",
        &format!(
            "op=call ms={} model={} input_tokens={} output_tokens={} cache_write_tokens={} cache_read_tokens={} prompt_chars={} command_chars={} tool_chars={} existing_chars={} context_chars={} result_chars={} upgraded={} ctx={} result={} redactions={} concurrent={} id={}",
            ms,
            model,
            input_tokens,
            output_tokens,
            cache_write_tokens,
            cache_read_tokens,
            prompt_chars,
            command_chars,
            tool_chars,
            existing_chars,
            context_chars,
            result_chars,
            if existing.is_empty() { 0 } else { 1 },
            if context.is_empty() { 0 } else { 1 },
            if result_head.is_empty() { 0 } else { 1 },
            redactions,
            describe_concurrent,
            id
        ),
    );
    let body = serde_json::json!({ "ok": true, "description": desc });
    (200, JSON, body.to_string().into_bytes())
}

// hook-trace-follow-settings: the PreToolUse guards POST their [hook]
// decision lines here instead of appending to the trace file gated on
// spawn-time BRAM_TRACE env (which desynced from the Settings toggle for
// the lifetime of a running agent). append_bram_trace_line is gated on
// the LIVE trace setting, so the toggle takes effect immediately.
fn handle_hook_trace<R: tauri::Runtime>(
    app: &AppHandle<R>,
    body: &[u8],
) -> (u16, &'static str, Vec<u8>) {
    const JSON: &str = "application/json; charset=utf-8";
    let v: serde_json::Value = match serde_json::from_slice(body) {
        Ok(v) => v,
        Err(_) => return (400, JSON, b"{\"ok\":false}".to_vec()),
    };
    let field = |k: &str| -> String {
        v.get(k)
            .and_then(|x| x.as_str())
            .unwrap_or("")
            .replace(['\n', '\r'], " ")
    };
    append_bram_trace_line(
        app,
        "hook",
        &format!(
            "script={} event={} tool={} target={} cwd={} decision={} reason={}",
            field("script"),
            field("event"),
            field("tool"),
            field("target"),
            field("cwd"),
            field("decision"),
            field("reason")
        ),
    );
    (200, JSON, b"{\"ok\":true}".to_vec())
}

// issue-355: parse the de-facto `dataType="sql"` wire body — `{sql, params}`
// (params optional), a JSON string, or bare text treated as the SQL (the
// XMLUI runtime's fallback shapes). Pure and unit-tested.
fn parse_query_route_body(bytes: &[u8]) -> Result<(String, Vec<serde_json::Value>), String> {
    let text = String::from_utf8_lossy(bytes);
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return Err("empty body — POST {\"sql\": \"...\", \"params\": [...]}".to_string());
    }
    if let Ok(v) = serde_json::from_str::<serde_json::Value>(trimmed) {
        return match v {
            serde_json::Value::String(s) => Ok((s, Vec::new())),
            serde_json::Value::Object(map) => {
                let sql = map
                    .get("sql")
                    .and_then(|s| s.as_str())
                    .unwrap_or("")
                    .to_string();
                if sql.trim().is_empty() {
                    return Err("body object has no \"sql\"".to_string());
                }
                let params = map
                    .get("params")
                    .and_then(|p| p.as_array())
                    .cloned()
                    .unwrap_or_default();
                Ok((sql, params))
            }
            _ => Err("body must be {sql, params} or a SQL string".to_string()),
        };
    }
    Ok((trimmed.to_string(), Vec::new()))
}

fn query_param_to_sql(v: &serde_json::Value) -> Box<dyn rusqlite::ToSql> {
    match v {
        serde_json::Value::Null => Box::new(rusqlite::types::Null),
        serde_json::Value::Bool(b) => Box::new(*b),
        serde_json::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Box::new(i)
            } else {
                Box::new(n.as_f64().unwrap_or(0.0))
            }
        }
        serde_json::Value::String(s) => Box::new(s.clone()),
        other => Box::new(other.to_string()),
    }
}

fn sqlite_value_to_json(v: rusqlite::types::ValueRef) -> serde_json::Value {
    use rusqlite::types::ValueRef;
    match v {
        ValueRef::Null => serde_json::Value::Null,
        ValueRef::Integer(i) => serde_json::json!(i),
        ValueRef::Real(f) => serde_json::json!(f),
        ValueRef::Text(t) => serde_json::Value::String(String::from_utf8_lossy(t).into_owned()),
        ValueRef::Blob(b) => serde_json::Value::String(String::from_utf8_lossy(b).into_owned()),
    }
}

// issue-355: read-only execution, enforced twice — the read-only open flag
// AND `PRAGMA query_only` — so the route cannot mutate regardless of
// statement text. No fragile is-it-a-SELECT string filtering: the engine
// is the enforcement.
fn execute_readonly_query(
    db_path: &Path,
    sql: &str,
    params: &[serde_json::Value],
) -> Result<Vec<serde_json::Value>, String> {
    let conn = rusqlite::Connection::open_with_flags(
        db_path,
        rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY | rusqlite::OpenFlags::SQLITE_OPEN_NO_MUTEX,
    )
    .map_err(|e| e.to_string())?;
    conn.pragma_update(None, "query_only", true)
        .map_err(|e| e.to_string())?;
    let mut stmt = conn.prepare(sql).map_err(|e| e.to_string())?;
    let col_names: Vec<String> = stmt.column_names().iter().map(|s| s.to_string()).collect();
    let bound: Vec<Box<dyn rusqlite::ToSql>> = params.iter().map(query_param_to_sql).collect();
    let refs: Vec<&dyn rusqlite::ToSql> = bound.iter().map(|b| b.as_ref()).collect();
    let mut rows = stmt
        .query(rusqlite::params_from_iter(refs))
        .map_err(|e| e.to_string())?;
    let mut out = Vec::new();
    while let Some(row) = rows.next().map_err(|e| e.to_string())? {
        let mut obj = serde_json::Map::new();
        for (i, name) in col_names.iter().enumerate() {
            let value = row.get_ref(i).map_err(|e| e.to_string())?;
            obj.insert(name.clone(), sqlite_value_to_json(value));
        }
        out.push(serde_json::Value::Object(obj));
    }
    Ok(out)
}

// issue-355: POST /query — the receiving end of XMLUI's
// `DataSource dataType="sql"`, scoped to the ONE database the project
// explicitly designates (`.bram.json` "db", resolved within the project
// root). The route is a dev-time instrument: Bram's loopback is the
// default project-content upstream, so relative `/query` from target
// markup lands here in both the embedded pane and a browser view; a
// project running its own dev server implements its own endpoint against
// the same wire contract.
fn handle_query_route<R: tauri::Runtime>(
    app: &AppHandle<R>,
    body: &[u8],
) -> (u16, &'static str, Vec<u8>) {
    const TEXT: &str = "text/plain; charset=utf-8";
    let Some(root) = project_root(Some(app)) else {
        return (500, TEXT, b"no project root".to_vec());
    };
    let Some(db_rel) = load_project_config(&root).and_then(|c| c.db) else {
        append_bram_trace_line(app, "query-route", "op=refuse reason=no-db");
        return (
            409,
            TEXT,
            b"no database configured - set \"db\": \"<relative path>\" in .bram.json".to_vec(),
        );
    };
    let root_canon = strip_unc_prefix(root.canonicalize().unwrap_or_else(|_| root.clone()));
    let candidate = root.join(&db_rel);
    let db_path = match candidate.canonicalize() {
        Ok(p) => strip_unc_prefix(p),
        Err(e) => {
            append_bram_trace_line(app, "query-route", "op=refuse reason=db-missing");
            return (
                409,
                TEXT,
                format!("configured db {} not readable: {}", db_rel, e).into_bytes(),
            );
        }
    };
    if !db_path.starts_with(&root_canon) {
        append_bram_trace_line(app, "query-route", "op=refuse reason=db-outside-root");
        return (
            403,
            TEXT,
            b"configured db resolves outside the project root".to_vec(),
        );
    }
    let (sql, params) = match parse_query_route_body(body) {
        Ok(parsed) => parsed,
        Err(e) => {
            append_bram_trace_line(app, "query-route", "op=refuse reason=bad-body");
            return (400, TEXT, e.into_bytes());
        }
    };
    let started = std::time::Instant::now();
    match execute_readonly_query(&db_path, &sql, &params) {
        Ok(rows) => {
            if bram_trace_enabled() {
                append_bram_trace_line(
                    app,
                    "query-route",
                    &format!(
                        "op=ok rows={} ms={}",
                        rows.len(),
                        started.elapsed().as_millis()
                    ),
                );
            }
            let body = serde_json::to_vec(&rows).unwrap_or_else(|_| b"[]".to_vec());
            (200, "application/json; charset=utf-8", body)
        }
        Err(e) => {
            if bram_trace_enabled() {
                append_bram_trace_line(
                    app,
                    "query-route",
                    &format!("op=sql-error detail={}", e.replace(['\n', '\r'], " ")),
                );
            }
            (400, TEXT, e.into_bytes())
        }
    }
}

#[cfg(test)]
mod query_route_tests {
    use super::{execute_readonly_query, parse_query_route_body};

    fn fixture_db(name: &str) -> std::path::PathBuf {
        let path =
            std::env::temp_dir().join(format!("bram-query-{}-{}.db", name, std::process::id()));
        let _ = std::fs::remove_file(&path);
        let conn = rusqlite::Connection::open(&path).expect("create fixture db");
        conn.execute_batch(
            "CREATE TABLE txns (id INTEGER PRIMARY KEY, memo TEXT, amount REAL);
             INSERT INTO txns VALUES (1, 'coffee', 4.5), (2, 'rent', 1200.0);",
        )
        .expect("seed fixture");
        path
    }

    #[test]
    fn body_shapes_object_string_and_bare_text() {
        let (sql, params) =
            parse_query_route_body(br#"{"sql":"SELECT * FROM t WHERE id = ?","params":[7]}"#)
                .expect("object parses");
        assert_eq!(sql, "SELECT * FROM t WHERE id = ?");
        assert_eq!(params, vec![serde_json::json!(7)]);
        let (sql, params) = parse_query_route_body(br#""SELECT 1""#).expect("JSON string parses");
        assert_eq!((sql.as_str(), params.len()), ("SELECT 1", 0));
        let (sql, _) = parse_query_route_body(b"SELECT 2").expect("bare text parses");
        assert_eq!(sql, "SELECT 2");
        assert!(parse_query_route_body(b"").is_err());
        assert!(parse_query_route_body(br#"{"params":[1]}"#).is_err());
    }

    #[test]
    fn rows_return_as_column_keyed_objects_with_params_bound() {
        let db = fixture_db("rows");
        let rows = execute_readonly_query(
            &db,
            "SELECT id, memo, amount FROM txns WHERE amount > ? ORDER BY id",
            &[serde_json::json!(10)],
        )
        .expect("query runs");
        assert_eq!(
            rows,
            vec![serde_json::json!({"id": 2, "memo": "rent", "amount": 1200.0})]
        );
        let _ = std::fs::remove_file(&db);
    }

    #[test]
    fn mutation_is_refused_by_the_engine() {
        let db = fixture_db("readonly");
        for sql in [
            "INSERT INTO txns VALUES (3, 'x', 1.0)",
            "UPDATE txns SET amount = 0",
            "DELETE FROM txns",
            "CREATE TABLE evil (a)",
            "DROP TABLE txns",
        ] {
            let err = execute_readonly_query(&db, sql, &[]).expect_err("mutation must fail");
            assert!(
                err.contains("readonly") || err.contains("read-only") || err.contains("attempt"),
                "unexpected error for {}: {}",
                sql,
                err
            );
        }
        // The data is intact afterwards.
        let rows =
            execute_readonly_query(&db, "SELECT COUNT(*) AS n FROM txns", &[]).expect("count runs");
        assert_eq!(rows, vec![serde_json::json!({"n": 2})]);
        let _ = std::fs::remove_file(&db);
    }
}

fn handle_http<R: tauri::Runtime>(app: &AppHandle<R>, mut request: tiny_http::Request) {
    let url = request.url().to_string();
    let method = request.method().as_str().to_uppercase();
    let (raw_path, query) = match url.split_once('?') {
        Some((p, q)) => (p, q),
        None => (url.as_str(), ""),
    };
    let path = raw_path.trim_start_matches('/');

    let route_correlation_id = next_route_correlation_id();
    let route_start = std::time::Instant::now();
    trace_route_entry(app, &method, path, query, &route_correlation_id);

    // issue-113-h6: the request Origin drives the CORS response. The agent
    // pane's cross-origin fetches to the loopback send NO Origin (confirmed by
    // soak: real pane traffic was 100% `(none)`), so those responses are not
    // CORS-restricted; the old `*` was load-bearing only for a genuinely
    // cross-origin browser caller (an attacker page). ACAO is now echoed only
    // for the shell origin at the response builder below, via
    // cors_allowed_origin.
    let request_origin: Option<String> = request
        .headers()
        .iter()
        .find(|h| h.field.equiv("Origin"))
        .map(|h| h.value.as_str().to_string());

    // POST-only routes (route_request is GET-only).
    let (status, content_type, body) = if path == "__self-update" {
        // clickable-update-from-banner: start the install flow (idempotent
        // guard: 409 while one runs). Progress rides /__self-update/status +
        // the self-update-changed event.
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            handle_self_update_start(app)
        }
    } else if path == "__self-update/relaunch" {
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            handle_self_update_relaunch(app)
        }
    } else if path == "query" {
        // issue-355: the dataType="sql" receiving end. Unprefixed on
        // purpose — target markup calls it with a relative URL, matching
        // the xmlui test server's de-facto contract.
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            let mut buf = Vec::new();
            let _ = request.as_reader().read_to_end(&mut buf);
            handle_query_route(app, &buf)
        }
    } else if path == "__queue/save" {
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            let mut buf = Vec::new();
            let _ = request.as_reader().read_to_end(&mut buf);
            handle_queue_save(app, &buf)
        }
    } else if path == "__worklist/mutate" {
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            let mut buf = Vec::new();
            let _ = request.as_reader().read_to_end(&mut buf);
            handle_worklist_mutate(app, &buf)
        }
    } else if path == "__worklist/drop" {
        // issue-340: a host-direct drop. A drop is pure host work
        // (record-auth + resolve + prune), but routing it through an agent
        // turn gave an accidental Drop a ~90s uninterruptible window with no
        // cancel path in the pane. This route does all three atomically and
        // returns in milliseconds, so the destructive act has effectively no
        // in-flight window. The pane calls it for feedback-less drops instead
        // of toTurn-ing a `drop:` turn to the agent.
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            let mut buf = Vec::new();
            let _ = request.as_reader().read_to_end(&mut buf);
            handle_worklist_drop_direct(app, &buf)
        }
    } else if path == "__worklist/commit" {
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            let mut buf = Vec::new();
            let _ = request.as_reader().read_to_end(&mut buf);
            handle_worklist_commit(app, &buf)
        }
    } else if path == "__audit/direct-edit" {
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            let mut buf = Vec::new();
            let _ = request.as_reader().read_to_end(&mut buf);
            handle_audit_direct_edit(app, &buf)
        }
    } else if path == "__trace/pane" {
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            let mut buf = Vec::new();
            let _ = request.as_reader().read_to_end(&mut buf);
            handle_trace_pane(app, &buf)
        }
    } else if path == "__describe-command" {
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            let mut buf = Vec::new();
            let _ = request.as_reader().read_to_end(&mut buf);
            handle_describe_command(app, &buf)
        }
    } else if path == "__menu/permission" {
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            let mut buf = Vec::new();
            let _ = request.as_reader().read_to_end(&mut buf);
            handle_permission_menu(app, &buf, false)
        }
    } else if path == "__menu/permission/clear" {
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            let mut buf = Vec::new();
            let _ = request.as_reader().read_to_end(&mut buf);
            handle_permission_menu(app, &buf, true)
        }
    } else if path == "__hook-trace" {
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            let mut buf = Vec::new();
            let _ = request.as_reader().read_to_end(&mut buf);
            handle_hook_trace(app, &buf)
        }
    } else if path == "__worklist/end" {
        // The last-action route agents may call to close approved/drop
        // turns (the sentinel doesn't care which kind wrote it; the
        // clear logic only needs the id set). The legacy
        // `/__iterate/begin` + `/__iterate/end` routes were deleted
        // (delete-phase tranche 1, #214): the host sets and clears the
        // iterate sentinel on the toTurn write path, so no agent-side
        // bracket exists to serve. Closes #91.
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            let mut buf = Vec::new();
            let _ = request.as_reader().read_to_end(&mut buf);
            handle_iterate_end(app, &buf)
        }
    } else if path == "__needs-you/dismiss" {
        // inbox-dismiss-forge-items: record a (id, activityMarker) dismissal;
        // the serve drops matching forge items until new activity moves the
        // marker.
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            let mut buf = Vec::new();
            let _ = request.as_reader().read_to_end(&mut buf);
            handle_needs_you_dismiss(app, &buf)
        }
    } else if path == "__git/pull-rebase" {
        if method != "POST" {
            (405, "text/plain; charset=utf-8", b"POST only".to_vec())
        } else {
            handle_git_pull_rebase(app)
        }
    } else if path == "__settings" && method == "POST" {
        let mut buf = Vec::new();
        let _ = request.as_reader().read_to_end(&mut buf);
        handle_settings_post(app, &buf)
    } else if path == "__diff/annotate" && method == "POST" {
        let mut buf = Vec::new();
        let _ = request.as_reader().read_to_end(&mut buf);
        handle_diff_annotate(&buf)
    } else if path == "__paste-image" && method == "POST" {
        let mut buf = Vec::new();
        let _ = request.as_reader().read_to_end(&mut buf);
        handle_paste_image(query, &buf)
    } else {
        route_request(app, path, query)
    };

    let body_size = body.len();
    trace_route_exit(
        app,
        &method,
        path,
        &route_correlation_id,
        status,
        body_size,
        route_start.elapsed().as_millis(),
    );

    let mut response = tiny_http::Response::from_data(body)
        .with_status_code(status)
        .with_header(
            tiny_http::Header::from_bytes(&b"Content-Type"[..], content_type.as_bytes()).unwrap(),
        )
        .with_header(
            // Internal API endpoints serve live state (sessions JSONL, git
            // status, etc.). Browser HTTP caching would defeat polling.
            tiny_http::Header::from_bytes(
                &b"Cache-Control"[..],
                &b"no-store, no-cache, must-revalidate"[..],
            )
            .unwrap(),
        );
    // issue-113-h6: replace the wildcard ACAO (root cause #2). Echo the
    // header only for the shell origin (the agent-pane webview); omit it for
    // any other Origin and for no-Origin callers (the pane's own fetches and
    // curl, which need no CORS grant — their responses are not
    // CORS-restricted). A cross-origin browser page therefore cannot read the
    // response, and the target pane's `bramapp://localhost` origin is excluded
    // by not equalling SHELL_ORIGIN.
    if let Some(allowed) = cors_allowed_origin(request_origin.as_deref()) {
        response.add_header(
            tiny_http::Header::from_bytes(&b"Access-Control-Allow-Origin"[..], allowed.as_bytes())
                .unwrap(),
        );
    }
    let _ = request.respond(response);
}

// Shell-document origin string used as the prefix for URLs that load
// in the shell or in same-origin iframes. Tauri 2 presents the scheme
// differently per platform:
//   - macOS / iOS / Linux: `tauri://localhost/...`
//   - Windows / Android:   `http://tauri.localhost/...` (HTTP localhost
//     subdomain — browser policy treats this as a secure context, so
//     service workers work; the macOS form is custom-scheme and not a
//     secure context, so SW does not work there)
// The scheme NAME we register against (`tauri`) is the same across
// platforms; only the URL form the WebView sees changes. The iframe
// `src` we hand to the JS side must match the platform's actual form
// so navigations resolve to our scheme handler rather than 404.
#[cfg(any(target_os = "windows", target_os = "android"))]
const SHELL_ORIGIN: &str = "http://tauri.localhost";

#[cfg(not(any(target_os = "windows", target_os = "android")))]
const SHELL_ORIGIN: &str = "tauri://localhost";

// issue-113-h6: the sole Origin that receives a CORS grant is the shell
// (agent-pane) webview. No-Origin callers (the pane's own fetches, curl) and
// every other cross-origin browser page get none, so a malicious page cannot
// read loopback responses, and the target pane's bramapp:// origin is excluded
// by not equalling SHELL_ORIGIN. Pure for unit testing.
fn cors_allowed_origin(request_origin: Option<&str>) -> Option<&'static str> {
    match request_origin {
        Some(o) if o == SHELL_ORIGIN => Some(SHELL_ORIGIN),
        _ => None,
    }
}

#[cfg(test)]
mod cors_origin_tests {
    use super::{cors_allowed_origin, SHELL_ORIGIN};

    #[test]
    fn only_the_shell_origin_is_granted() {
        assert_eq!(cors_allowed_origin(None), None);
        assert_eq!(cors_allowed_origin(Some(SHELL_ORIGIN)), Some(SHELL_ORIGIN));
        assert_eq!(cors_allowed_origin(Some("http://evil.com")), None);
        assert_eq!(cors_allowed_origin(Some("bramapp://localhost")), None);
    }
}

// Distinct origin for the target-app pane so same-origin policy isolates it
// from the shell's `window.__TAURI__` and the loopback `/__*` routes
// (security C1 / #113, #112). Mirrors SHELL_ORIGIN's platform split: Tauri
// presents custom schemes as `http://<scheme>.localhost` (secure context) on
// Windows/Android and `<scheme>://localhost` elsewhere. The target pane is a
// pure display surface — see `handle_target_scheme`.
#[cfg(any(target_os = "windows", target_os = "android"))]
const TARGET_ORIGIN: &str = "http://bramapp.localhost";

#[cfg(not(any(target_os = "windows", target_os = "android")))]
const TARGET_ORIGIN: &str = "bramapp://localhost";

// Tauri custom-scheme handler that overrides Tauri's default tauri://
// behavior. Tauri 2 skips registering its built-in handler when an
// app-level handler with the same scheme name is present (see
// tauri-2.11.0/src/manager/webview.rs:267). With our handler in place:
//
//   - `tauri://localhost/__project/*` is proxied to the upstream URL in
//     PaneUrlsState.right_pane_upstream (the loopback HTTP server by
//     default, or an external project dev server when project config
//     declares one). The iframe's origin stays `tauri://localhost`, same
//     as the shell — same-origin policy then permits direct cross-frame
//     JS access. This is the whole point: shell and target can share
//     window globals (e.g., _xsLogs) without a postMessage bridge, and
//     the target reaches window.__TAURI__ directly.
//
//   - All other paths fall back to xd's own app/ tree via serve_app_file
//     (on-disk preferred, embedded fallback). Replicates Tauri's default
//     resource-loading behavior so the shell's own index.html, main.js,
//     vendor/*, __shell/*, __tools/* keep loading exactly as before.
//
// Hop-by-hop request and response headers are filtered out per RFC 7230.
// Connection failures to the upstream surface as 502 responses with a
// short error body so the iframe shows something rather than hanging.
fn handle_tauri_scheme<R: tauri::Runtime>(
    app: &AppHandle<R>,
    request: http::Request<Vec<u8>>,
) -> http::Response<Vec<u8>> {
    let uri = request.uri().clone();
    let path = uri.path();
    let rel = path.trim_start_matches('/');

    // Tier 1: /__project/* — project content escape hatch under the __
    // namespace. Strip prefix and proxy to right_pane_upstream (loopback
    // default or external dev server).
    if let Some(after) = rel.strip_prefix("__project/") {
        let upstream = {
            let state = app.state::<PaneUrlsState>();
            let urls = state.0.lock().unwrap();
            urls.right_pane_upstream.clone()
        };
        return proxy_to_target(upstream, after, uri.query(), request);
    }

    // Tier 2: shell assets from xd's app/ tree. Covers the shell's own
    // index.html, main.js, styles.css, vendor/*, and the tools pane at
    // tools/index.html + tools/components/*, tools/manual.md, etc.
    // Both panes can hit this directly via tauri://localhost/<path>.
    let app_rel = if rel.is_empty() { "index.html" } else { rel };
    if let Some((bytes, mime)) = serve_app_file(Some(app), app_rel) {
        return http::Response::builder()
            .status(200)
            .header("Content-Type", mime)
            .body(bytes)
            .unwrap_or_else(|_| {
                http::Response::builder()
                    .status(500)
                    .body(Vec::new())
                    .unwrap()
            });
    }

    // Tier 3: other /__* paths — xd-internal HTTP endpoints (sessions,
    // worklist, app-info, file, error, enhance, restart-server, etc.).
    // These always live on the loopback regardless of which project is
    // loaded; the loopback's own routing (route_request in lib.rs) knows
    // how to serve them. Includes the __vendor / __shell namespaces,
    // which the loopback maps to xd's app/vendor and app/__shell when
    // serve_app_file misses (e.g., for the `__vendor` -> `vendor`
    // prefix-strip mapping in the loopback's handler).
    if rel.starts_with("__") {
        let loopback = {
            let state = app.state::<PaneUrlsState>();
            let urls = state.0.lock().unwrap();
            urls.loopback_origin.clone()
        };
        return proxy_to_target(loopback, rel, uri.query(), request);
    }

    // Tier 4: everything else — project content at a non-`__*` absolute
    // path (e.g., /xmlui/foo.js for xmlui-weather, /Main.xmlui,
    // /resources/foo.svg). Proxy to right_pane_upstream so external dev
    // servers also work.
    let upstream = {
        let state = app.state::<PaneUrlsState>();
        let urls = state.0.lock().unwrap();
        urls.right_pane_upstream.clone()
    };
    proxy_to_target(upstream, rel, uri.query(), request)
}

// Isolation scheme for the target-app pane (security C1 / #113, #112). Served
// at a DISTINCT origin (TARGET_ORIGIN) from the shell, so same-origin policy
// denies target content `window.parent.__TAURI__`, the PTY-driving helpers,
// and the loopback's internal `/__*` routes. The target pane is a pure display
// surface with no host authority: only project content is proxied to
// `right_pane_upstream`; every Bram-internal route and shell asset (including
// `__shell/helpers.js`) is refused. Contrast `handle_tauri_scheme`, which
// deliberately keeps the shell and agent-tools drawer same-origin.
fn handle_target_scheme<R: tauri::Runtime>(
    app: &AppHandle<R>,
    request: http::Request<Vec<u8>>,
) -> http::Response<Vec<u8>> {
    let uri = request.uri().clone();
    let rel = uri.path().trim_start_matches('/');
    let (right_pane_upstream, loopback_origin) = {
        let state = app.state::<PaneUrlsState>();
        let urls = state.0.lock().unwrap();
        (
            urls.right_pane_upstream.clone(),
            urls.loopback_origin.clone(),
        )
    };
    // Self-diagnosing: one line per request so we can confirm the bramapp
    // scheme is actually routed to this handler (C1 build-gate probe).
    if bram_trace_enabled() {
        append_bram_trace_line(app, "target-scheme", &format!("op=enter rel={}", rel));
    }
    // /__project/* — project content escape hatch; strip the prefix and proxy
    // to the project upstream, exactly as the shell scheme's Tier 1 does, so
    // relative sub-resource URLs resolve identically at the isolated origin.
    if let Some(after) = rel.strip_prefix("__project/") {
        return proxy_to_target(right_pane_upstream, after, uri.query(), request);
    }
    if rel.starts_with("__") {
        // Static Bram assets the target legitimately needs to RENDER — vendored
        // libraries (`__vendor/*`: xmlui-standalone, xterm) and the helper shim
        // (`__shell/*`) — are served from the loopback like the shell scheme's
        // Tier 3. The shim is inert here: cross-origin, its `getTauriInvoke()`
        // cannot reach the shell's `window.__TAURI__`, so `toShell`/`toTurn`/
        // `sendKeys`/`open_url` no-op. What we REFUSE is the dynamic host-route
        // surface (`__file`, `__worklist/*`, `__issue/*`, `__context/*`,
        // `__local-file-preview`, `__settings`, `__menu/*`, `__git/*`, …) — the
        // loopback endpoints that read files, mutate git, or drive the PTY. The
        // origin boundary is the primary isolation; this is defense in depth.
        if rel.starts_with("__vendor/") || rel.starts_with("__shell/") {
            return proxy_to_target(loopback_origin, rel, uri.query(), request);
        }
        if bram_trace_enabled() {
            append_bram_trace_line(app, "target-scheme", &format!("op=refuse rel={}", rel));
        }
        return http::Response::builder()
            .status(403)
            .header("Content-Type", "text/plain; charset=utf-8")
            .body(b"forbidden: the target pane has no access to Bram host routes".to_vec())
            .unwrap_or_else(|_| {
                http::Response::builder()
                    .status(403)
                    .body(Vec::new())
                    .unwrap()
            });
    }
    // Project sub-resources at absolute non-`__` paths (e.g. /xmlui/foo.js,
    // /Main.xmlui) — proxy straight to the project upstream, mirroring the
    // shell scheme's Tier 4.
    proxy_to_target(right_pane_upstream, rel, uri.query(), request)
}

fn proxy_to_target(
    upstream_base: String,
    path_after_origin: &str,
    query: Option<&str>,
    request: http::Request<Vec<u8>>,
) -> http::Response<Vec<u8>> {
    let mut url = format!("{}{}", upstream_base, path_after_origin);
    if let Some(q) = query {
        url.push('?');
        url.push_str(q);
    }
    proxy_to_upstream(url, request)
}

fn proxy_to_upstream(url: String, request: http::Request<Vec<u8>>) -> http::Response<Vec<u8>> {
    let method = request.method().clone();
    let (parts, body) = request.into_parts();

    let mut req = ureq::request(method.as_str(), &url);
    for (name, value) in parts.headers.iter() {
        let name_str = name.as_str();
        // Skip hop-by-hop headers and Host (ureq sets Host automatically
        // from the request URL — forwarding the shell's `tauri.localhost`
        // would confuse the upstream).
        if is_hop_by_hop(name_str) || name_str.eq_ignore_ascii_case("host") {
            continue;
        }
        if let Ok(value_str) = value.to_str() {
            req = req.set(name_str, value_str);
        }
    }

    let result = if body.is_empty() {
        req.call()
    } else {
        req.send_bytes(&body)
    };

    let response = match result {
        Ok(r) => r,
        Err(ureq::Error::Status(_, r)) => r,
        Err(e) => {
            eprintln!("[scheme-proxy] {} {} -> {}", method, url, e);
            return http::Response::builder()
                .status(502)
                .header("Content-Type", "text/plain")
                .body(format!("upstream proxy error for {}: {}", url, e).into_bytes())
                .unwrap();
        }
    };

    let status = response.status();
    // Snapshot headers before consuming response into a reader.
    let header_names = response.headers_names();
    let header_pairs: Vec<(String, String)> = header_names
        .iter()
        .filter_map(|name| response.header(name).map(|v| (name.clone(), v.to_string())))
        .collect();

    let mut body_bytes = Vec::new();
    if let Err(e) = response.into_reader().read_to_end(&mut body_bytes) {
        eprintln!("[scheme-proxy] read error from {}: {}", url, e);
        return http::Response::builder()
            .status(502)
            .header("Content-Type", "text/plain")
            .body(format!("upstream read error: {}", e).into_bytes())
            .unwrap();
    }

    let mut builder = http::Response::builder().status(status);
    for (name, value) in header_pairs {
        if is_hop_by_hop(&name) {
            continue;
        }
        builder = builder.header(&name, &value);
    }
    builder.body(body_bytes).unwrap_or_else(|_| {
        http::Response::builder()
            .status(502)
            .body(Vec::new())
            .unwrap()
    })
}

fn is_hop_by_hop(name: &str) -> bool {
    matches!(
        name.to_ascii_lowercase().as_str(),
        "connection"
            | "keep-alive"
            | "proxy-authenticate"
            | "proxy-authorization"
            | "te"
            | "trailers"
            | "transfer-encoding"
            | "upgrade"
    )
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
// Bump RLIMIT_NOFILE on Unix so tiny_http's accept loop doesn't panic
// on EMFILE during long sessions. macOS default soft limit is often 256,
// which is too low once the filesystem watcher, iframe scheme-proxy,
// session-JSONL pollers, etc. accumulate. Target 8192 (or hard limit
// if lower). No-op on Windows — different FD semantics. See issue #44.
#[cfg(unix)]
fn raise_open_files_limit() {
    use libc::{getrlimit, rlimit, setrlimit, RLIMIT_NOFILE};
    unsafe {
        let mut current = rlimit {
            rlim_cur: 0,
            rlim_max: 0,
        };
        if getrlimit(RLIMIT_NOFILE, &mut current) != 0 {
            eprintln!("[rlimit] getrlimit failed; not bumping");
            return;
        }
        let target: libc::rlim_t = 8192;
        let new_cur = std::cmp::min(target, current.rlim_max);
        if new_cur <= current.rlim_cur {
            eprintln!(
                "[rlimit] soft={} already meets target={}; not bumping",
                current.rlim_cur, target
            );
            return;
        }
        let new_limits = rlimit {
            rlim_cur: new_cur,
            rlim_max: current.rlim_max,
        };
        if setrlimit(RLIMIT_NOFILE, &new_limits) == 0 {
            eprintln!(
                "[rlimit] bumped soft FD limit {} -> {} (hard={})",
                current.rlim_cur, new_cur, current.rlim_max
            );
        } else {
            eprintln!(
                "[rlimit] setrlimit failed; staying at soft={}",
                current.rlim_cur
            );
        }
    }
}

#[cfg(not(unix))]
fn raise_open_files_limit() {}

pub fn run() {
    raise_open_files_limit();
    parse_cli_flags();
    init_bram_trace_from_env();
    // Refresh the ~/.bram/bram-guard link so hook registrations survive app
    // moves and updates (bram-guard-reentrant-menu-hooks). Best-effort.
    let _ = guard::ensure_bram_guard_link();
    let initial_proj = determine_project_root();
    eprintln!("[bram] project root: {}", initial_proj.display());
    // Apply project config at boot. The menu-setting defaults MUST apply
    // even when there is no .bram.json (fix-menu-defaults-without-bram-json):
    // the atomics init false, so gating the apply on config presence left a
    // freshly-cloned project (no .bram.json) with hook_driven=false ->
    // handle_permission_menu early-returns applied:false, and
    // parse_and_display=false disables the grid fallback, so NO menus surface
    // at all. Read through cfg.as_ref() so None still yields the intended
    // defaults (hook_driven=true, parse_and_display=false). Traces default
    // ON: absent setting resolves to true here (init_bram_trace_from_env
    // already seeded the same default pre-config); an explicit false in
    // .bram.json, or a BRAM_TRACE env override (which wins inside
    // apply_bram_trace_from_config), turns tracing off.
    let cfg = load_project_config(&initial_proj);
    apply_bram_trace_from_config(
        cfg.as_ref()
            .and_then(|c| c.traces.as_ref())
            .and_then(|t| t.enabled)
            .unwrap_or(true),
    );
    apply_bram_menus_parse_from_config(
        cfg.as_ref()
            .and_then(|c| c.menus.as_ref())
            .and_then(|m| m.parse_and_display)
            .unwrap_or(false),
    );
    apply_bram_menus_hook_driven_from_config(
        cfg.as_ref()
            .and_then(|c| c.menus.as_ref())
            .and_then(|m| m.hook_driven)
            .unwrap_or(true),
    );
    // Only warn when the target pane is actually enabled (#275). The pane is
    // off by default -- most users preview their app in their own browser --
    // so telling a user that a pane they do not use will fail to load is noise
    // about a consequence that cannot occur.
    let target_pane_enabled = cfg
        .as_ref()
        .and_then(|c| c.ui.as_ref())
        .and_then(|u| u.show_target_app)
        .unwrap_or(false);
    if target_pane_enabled && !initial_proj.join("index.html").exists() {
        eprintln!(
            "[bram] WARNING: no index.html at project root; the right pane will fail to load. Run with `bram /path/to/project` or cd into the project before launching."
        );
    }
    tauri::Builder::default()
        .register_asynchronous_uri_scheme_protocol("tauri", |ctx, request, responder| {
            // Offload to a thread so the WebView's request thread is not
            // blocked while the proxy fetches from the upstream. The
            // responder takes ownership and can be called from any thread.
            let app = ctx.app_handle().clone();
            std::thread::spawn(move || {
                let response = handle_tauri_scheme(&app, request);
                responder.respond(response);
            });
        })
        .register_asynchronous_uri_scheme_protocol("bramapp", |ctx, request, responder| {
            // Isolation origin for the target-app pane (C1). Serves project
            // content only; runs on its own thread like the shell scheme.
            let app = ctx.app_handle().clone();
            std::thread::spawn(move || {
                let response = handle_target_scheme(&app, request);
                responder.respond(response);
            });
        })
        .plugin(tauri_plugin_opener::init())
        .plugin(tauri_plugin_window_state::Builder::default().build())
        .manage(AppState::default())
        .manage(WhisperState::default())
        .manage(SpawnedServerState::default())
        .manage(ActiveProjectState(Mutex::new(initial_proj)))
        .manage(PaneUrlsState(Mutex::new(PaneUrls::default())))
        .invoke_handler(tauri::generate_handler![
            pty_spawn,
            pty_write,
            switch_agent,
            reload_agent_session,
            create_new_session,
            queue_pty_intent,
            queue_feedback_draft,
            record_worklist_action_authorization,
            pty_resize,
            log_from_right_pane,
            report_grid_menu,
            report_grid_status,
            report_grid_banner,
            open_devtools,
            open_url,
            save_trace_export,
            capture_screenshot,
            git_push,
            issue_close_manual,
            get_right_pane_url,
            get_tools_pane_url,
            whisper_start,
            whisper_stop,
            whisper_status,
        ])
        .setup(move |app| {
            use tauri::Emitter;

            // Bind the right-pane HTTP server before anything else so the
            // URL is available the moment the parent shell asks for it.
            // Try the previous run's port first — when free, the Claude
            // permission allowlist (which matches literal port numbers,
            // not variables) keeps working without re-prompts. Fall back
            // to ephemeral when the previous port is held by anything
            // else, including a second Bram instance.
            let startup_project_root = project_root(Some(app.handle()));
            set_shell_window_title(app.handle());
            let previous_port = startup_project_root
                .as_ref()
                .and_then(|p| std::fs::read_to_string(p.join("resources/.bram-port")).ok())
                .and_then(|s| s.trim().parse::<u16>().ok())
                .filter(|&p| (49152..=65535).contains(&p));
            let (server, sticky) = match previous_port {
                Some(prev) => match tiny_http::Server::http(format!("127.0.0.1:{}", prev)) {
                    Ok(s) => (s, true),
                    Err(_) => (
                        tiny_http::Server::http("127.0.0.1:0").map_err(|e| {
                            format!("failed to bind right-pane http server: {}", e)
                        })?,
                        false,
                    ),
                },
                None => (
                    tiny_http::Server::http("127.0.0.1:0")
                        .map_err(|e| format!("failed to bind right-pane http server: {}", e))?,
                    false,
                ),
            };
            let port = server
                .server_addr()
                .to_ip()
                .map(|sa| sa.port())
                .ok_or("right-pane server bound to non-ip address")?;
            let _ = LOOPBACK_PORT.set(port);
            let started_at_ms = unix_now_ms();
            let _ = LOOPBACK_STARTED_MS.set(started_at_ms);
            eprintln!("[bram] loopback port={} sticky={}", port, sticky);
            if let Some(proj) = startup_project_root.as_ref() {
                remove_bram_port_files(proj);
                // issue-217: startup is the safe cutover point for the
                // hook rename — no Bram-spawned session exists yet.
                prune_legacy_claude_hooks(proj);
            }
            prepare_bram_trace_log(app.handle());
            trace_whisper_env(app.handle());
            // issue-230 unified search: background Claude-session indexer.
            start_search_indexer(app.handle().clone());
            if bram_trace_enabled() {
                append_bram_trace_line(
                    app.handle(),
                    "jsonl-turn-end",
                    "op=init providers=claude,codex codexMarker=event_msg/task_complete",
                );
            }
            // Remove any stale inflight sentinel from a prior session
            // that didn't complete cleanly. Refs #84.
            cleanup_stale_inflight_claim(app.handle());
            // Remove any stale Codex lifecycle intent/result files from a
            // prior session. Refs #130.
            cleanup_stale_worklist_intent(app.handle());
            // Windows self-update leaves renamed-aside *.exe.old files
            // (clickable-update-from-banner); delete them best-effort.
            cleanup_self_update_leftovers();
            // warn-when-git-toplevel-above-root: name the enclosing-repo
            // condition once at startup, at the cause (the same family as
            // nestedUnder / strayHomeScaffold). The pane banner keys off
            // /__enhance/status's gitToplevel; this line is the greppable
            // record that the launch began in that state.
            trace_git_toplevel_above_root(app.handle());
            // issue-350-stranded-approval-reconciliation: a stranded approval
            // survives relaunch (its turn's pty-intent does not, by #86's
            // design), so name it at startup too — the trace dedupe keeps
            // this and the board serve from double-logging one record.
            let _ = stranded_approval_ids(app.handle());
            // Remove any stale pty-intent queue from a prior session so
            // its intents don't replay into the fresh PTY. Refs #86.
            cleanup_stale_pty_intents(app.handle());
            // issue-338: warm the forge-notifications snapshot in the
            // background so opening Awaiting You never waits on gh, then
            // keep it fresh on a 90s cadence, emitting needs-you-changed
            // only when the (id, marker) signature moves.
            spawn_forge_awaiting_refresher(app.handle().clone());
            let internal_origin = format!("http://127.0.0.1:{}", port);
            eprintln!("[bram] internal HTTP server: {}", internal_origin);
            // Tools pane lives at xd's app/tools/index.html, served via
            // the scheme handler's Tier 2 (shell asset) directly. Same
            // origin as the shell. SHELL_ORIGIN picks the right URL form
            // per platform — see the const definition above.
            let tools_url = format!("{}/tools/index.html", SHELL_ORIGIN);

            // .bram.json may declare an external server for the
            // right pane. The tools-pane URL always points at the internal
            // loopback (so the drawer keeps working regardless).
            let project_cfg = project_root(Some(app.handle()))
                .as_deref()
                .and_then(load_project_config);
            let default_right_pane = format!("{}/index.html", internal_origin);
            let internal_base = format!("{}/", internal_origin);
            // `right_pane` is the URL the iframe loads. With the
            // tauri:// scheme proxy, it's always a same-origin URL
            // under /__project/. `right_pane_upstream` is the bare
            // origin (http://host:port/) the scheme handler proxies
            // to; the configured `cfg.path` (including any query)
            // gets spliced into the iframe URL so the browser's own
            // relative-URL resolution produces clean sub-resource
            // paths that pass through the proxy unchanged.
            let (right_pane_url, right_pane_upstream) = if let Some(cfg) = project_cfg.as_ref().and_then(|c| c.server.as_ref()) {
                let external_origin = format!("http://localhost:{}/", cfg.port);
                let right_pane_external = {
                    let path = if cfg.path.starts_with('/') {
                        cfg.path.clone()
                    } else {
                        format!("/{}", cfg.path)
                    };
                    format!("{}/__project{}", TARGET_ORIGIN, path)
                };
                // issue-341: a wedged port is now reaped, not refused, when
                // the sidecar can verify the orphan is OURS (recorded pid
                // still running the recorded command). Success re-probes as
                // NotListening and falls into the normal spawn path below.
                let mut probed = probe_port_http(cfg.port, &cfg.path);
                if let PortStatus::Unresponsive(_) = &probed {
                    if let Some(root) = project_root(Some(app.handle())) {
                        if try_reap_orphan_server(cfg, &root) {
                            append_bram_trace_line(
                                app.handle(),
                                "server",
                                &format!("op=orphan-reaped port={}", cfg.port),
                            );
                            probed = PortStatus::NotListening;
                        } else {
                            append_bram_trace_line(
                                app.handle(),
                                "server",
                                &format!("op=orphan-reap-declined port={}", cfg.port),
                            );
                        }
                    }
                }
                match probed {
                    PortStatus::Live => {
                        eprintln!(
                            "[server] port {} is live (HTTP responsive); reusing (skipping spawn of `{}`)",
                            cfg.port, cfg.command
                        );
                        (right_pane_external.clone(), external_origin.clone())
                    }
                    PortStatus::Unresponsive(reason) => {
                        eprintln!(
                            "[server] port {} is in use but unresponsive ({}); refusing to reuse",
                            cfg.port, reason
                        );
                        eprintln!(
                            "[server] HINT: a previous server is likely wedged. Run `lsof -i :{}` to find the pid, then kill it and restart Bram.",
                            cfg.port
                        );
                        // Surface the problem in the iframe via /__error
                        // on the internal loopback (the scheme handler
                        // proxies there; the iframe's URL stays under
                        // /__project so origin remains tauri://localhost).
                        let error_path = format!(
                            "__project/__error?reason={}",
                            percent_encode(&format!(
                                "Port {} is in use but unresponsive ({}). The previous Bram session likely left an orphan process. Run `lsof -i :{}` and kill the listed pid, then restart Bram.",
                                cfg.port, reason, cfg.port
                            ))
                        );
                        (
                            format!("{}/{}", SHELL_ORIGIN, error_path),
                            internal_base.clone(),
                        )
                    }
                    PortStatus::NotListening => {
                        if let Some(root) = project_root(Some(app.handle())) {
                            match spawn_project_server(cfg, &root) {
                                Ok(child) => {
                                    *app.state::<SpawnedServerState>().0.lock().unwrap() =
                                        Some(SpawnedServer {
                                            child,
                                            config: cfg.clone(),
                                        });
                                    if !wait_for_port(cfg.port, 5000) {
                                        eprintln!(
                                            "[server] WARNING: port {} did not come up within 5s; right-pane iframe will retry",
                                            cfg.port
                                        );
                                    } else {
                                        eprintln!("[server] port {} is up", cfg.port);
                                    }
                                }
                                Err(e) => {
                                    eprintln!("[server] spawn failed: {} — falling back to internal URL", e);
                                }
                            }
                        }
                        (right_pane_external.clone(), external_origin.clone())
                    }
                }
            } else {
                (
                    format!("{}/__project/index.html", TARGET_ORIGIN),
                    internal_base.clone(),
                )
            };
            eprintln!("[bram] right pane URL: {}", right_pane_url);
            eprintln!("[bram] right pane upstream: {}", right_pane_upstream);
            eprintln!("[bram] tools pane URL: {}", tools_url);
            *app.state::<PaneUrlsState>().0.lock().unwrap() = PaneUrls {
                right_pane: right_pane_url,
                tools: tools_url,
                default_right_pane,
                right_pane_upstream,
                loopback_origin: internal_base.clone(),
            };

            let server_app = app.handle().clone();
            std::thread::spawn(move || {
                for request in server.incoming_requests() {
                    let app = server_app.clone();
                    std::thread::spawn(move || handle_http(&app, request));
                }
            });
            // Publish the loopback port only after the accept loop is
            // actually serving HTTP. Otherwise agents can race startup:
            // lsof shows a listener, but curl still gets connection refused.
            if let Some(proj) = startup_project_root.as_ref() {
                let port_path = proj.join("resources/.bram-port");
                // issue-353: never scaffold the home directory. The port
                // files are the write that creates ~/resources on a
                // mis-launch, and everything under home then reads as
                // nested. Stderr only — trace persistence is likewise
                // refused at a home root (bram_trace_log_file).
                if project_root_is_home() {
                    eprintln!(
                        "[bram] op=refuse-home-scaffold root={} — project root is the home \
                         directory; startup scaffold (port files, trace directory) not written \
                         (issue #353)",
                        proj.display()
                    );
                } else if wait_for_loopback_http(port, 5000) {
                    match write_bram_port_files(proj, port, started_at_ms) {
                        Ok(()) => eprintln!(
                            "[bram] wrote ready port files: {}, {}",
                            port_path.display(),
                            bram_port_metadata_path(&port_path).display()
                        ),
                        Err(e) => eprintln!(
                            "[bram] failed to write ready port files for {}: {}",
                            port_path.display(),
                            e
                        ),
                    }
                } else {
                    eprintln!(
                        "[bram] loopback port {} did not become HTTP-ready; leaving {} unpublished",
                        port,
                        port_path.display()
                    );
                }
            }

            let Some(proj_root) = project_root(Some(app.handle())) else {
                eprintln!("[watcher] could not resolve project root");
                return Ok(());
            };
            // Seed the worklist cache so the first detected change can
            // diff against the on-disk baseline rather than treating the
            // entire current file as "new".
            init_worklist_cache(app.handle());
            // Seed a replayable talk-session tick before the tools iframe
            // subscribes; /__startup-ready replays this event on boot.
            emit_talk_session_changed(app.handle());
            // Seed host-owned settings for the same late-subscriber case.
            // Settings.xmlui consumes this full payload directly through a
            // PushSource, so it has no bootstrap DataSource fallback.
            let initial_settings = settings_view_from_config(load_project_config(&proj_root));
            emit_settings_changed(app.handle(), &initial_settings);
            // Watch contract: events are emitted on two channels, NOT one.
            //   - "right-pane-reload" fires for changes inside proj_root only;
            //     main.js reloads the right-pane iframe alone. The agent
            //     tools drawer is poll-driven, so it does NOT need to reload
            //     when user-project files change. Keeping the drawer iframe
            //     stable here prevents postMessage-into-torn-down-iframe
            //     races on Approve/Drop clicks.
            //   - "tools-pane-reload" fires for changes under app/__shell,
            //     app/vendor, or app/tools; main.js reloads BOTH iframes
            //     (the drawer's own code changed, and the right pane may
            //     consume __shell/helpers.js too).
            // Do not collapse these back into a single event.
            let proj_root_path = proj_root.clone();
            let mut tools_pane_paths: Vec<std::path::PathBuf> = Vec::new();
            if let Some(app_root) = resolve_app_root(Some(app.handle())) {
                tools_pane_paths.push(app_root.join("__shell"));
                tools_pane_paths.push(app_root.join("vendor"));
                tools_pane_paths.push(app_root.join("tools"));
            } else {
                eprintln!("[watcher] no on-disk app/; using embedded tree (no app/ reload)");
            }
            // Provider session JSONLs get their own dispatch. Watch the
            // containing roots (not the file — the file rotates per session
            // and may not exist at startup) so the tools pane can refetch
            // immediately instead of waiting on fallback polling.
            let claude_sessions_dir = claude_sessions_dir(&app.handle()).ok();
            let codex_sessions_dir = home_dir().map(|h| h.join(".codex").join("sessions"));
            // #212 trace: record the session dirs the watcher resolved at
            // startup. `claude=unresolved` (or a path that doesn't match where
            // Claude actually writes) is the smoking gun for the intermittent
            // stuck-working bug -- the watcher never sees the active Claude
            // session's end_turn writes, so state=finished never fires. Pairs
            // with the claude-finished-probe / op=provider-mismatch probes.
            if bram_trace_enabled() {
                // claude_exists / codex_exists are the dead-watch predicate: a
                // recursive watch registered on a path that does not exist yet
                // never fires when the dir is later created (#212 root cause).
                // Claude's per-project dir can be absent at startup; Codex's
                // global ~/.codex/sessions effectively always exists -- so
                // claude_exists=false here is the one-line stuck-working signal.
                let cl = claude_sessions_dir.as_ref();
                let cx = codex_sessions_dir.as_ref();
                append_bram_trace_line(
                    &app.handle(),
                    "watcher",
                    &format!(
                        "op=session-dirs claude={} claude_exists={} codex={} codex_exists={}",
                        cl.map(|p| p.display().to_string())
                            .unwrap_or_else(|| "unresolved".to_string()),
                        cl.map(|p| p.is_dir()).unwrap_or(false),
                        cx.map(|p| p.display().to_string())
                            .unwrap_or_else(|| "unresolved".to_string()),
                        cx.map(|p| p.is_dir()).unwrap_or(false),
                    ),
                );
            }
            // Current-provider record lives at
            // <app_cache>/current-agent/<encoded-cwd>.json and is written by the
            // host (set_current_provider) on deliberate transitions: autostart,
            // header switch, session resume. Watching this dir lets the
            // agent-tools drawer refetch /__enhance/status when the active
            // provider changes.
            let current_agent_dir = active_agent_hint_path(&app.handle())
                .ok()
                .and_then(|p| p.parent().map(|p| p.to_path_buf()));
            // ~/.bram/ holds Bram's user-global Codex hook. Ensure it exists at
            // startup so the watcher can attach to user-global Bram changes.
            let bram_dir = home_dir().map(|h| h.join(".bram"));
            if let Some(ref bd) = bram_dir {
                let _ = std::fs::create_dir_all(bd);
            }
            let mut watch_paths: Vec<std::path::PathBuf> = vec![proj_root_path.clone()];
            watch_paths.extend(tools_pane_paths.iter().cloned());
            if let Some(ref sd) = claude_sessions_dir {
                // #212 fix: watch the STABLE parent (~/.claude/projects/) rather
                // than the per-project leaf. The leaf may not exist at startup
                // (first Claude session in a project, or moved aside) and a
                // recursive watch registered on a non-existent dir never fires
                // when the dir is later created -- the dead watch that left
                // Claude's end_turn unscanned and the status stuck "working".
                // The recursive parent watch sees the leaf's creation and the
                // JSONL writes inside it; the session-event filter below still
                // gates dispatch on `p.starts_with(claude_sessions_dir)` (the
                // leaf), so this does not broaden what gets scanned. Create the
                // parent if absent (Claude makes it anyway) so the watch is live
                // from the first turn. Codex is left as-is: its global
                // ~/.codex/sessions effectively always exists.
                let watch_target = sd
                    .parent()
                    .map(|p| p.to_path_buf())
                    .unwrap_or_else(|| sd.clone());
                if !watch_target.is_dir() {
                    let _ = std::fs::create_dir_all(&watch_target);
                }
                if watch_target.is_dir() {
                    watch_paths.push(watch_target);
                }
            }
            if let Some(ref sd) = codex_sessions_dir {
                if sd.exists() {
                    watch_paths.push(sd.clone());
                }
            }
            if let Some(ref bd) = bram_dir {
                if bd.exists() {
                    watch_paths.push(bd.clone());
                }
            }
            if let Some(ref ah) = current_agent_dir {
                if ah.exists() {
                    watch_paths.push(ah.clone());
                }
            }
            let app_handle = app.handle().clone();
            start_codex_session_poll_fallback(app_handle.clone());
            start_claude_turn_stats_poll(app_handle.clone());
            start_git_head_watch(app_handle.clone());
            // issue-253: the refs watcher only helps if Bram was running when
            // the push happened, and the reported case is a release script with
            // the app closed. One attempt at startup covers it; the flush's own
            // empty-queue guard makes the ordinary launch a single file read.
            // Off the setup thread so a queue with work can't stall startup on
            // forge calls.
            let close_flush_handle = app_handle.clone();
            std::thread::spawn(move || {
                flush_pending_issue_closes(&close_flush_handle, "startup");
            });
            std::thread::spawn(move || {
                use notify::{recommended_watcher, Event, EventKind, RecursiveMode, Watcher};
                use std::sync::mpsc::channel;
                use std::time::{Duration, Instant};

                let (tx, rx) = channel::<notify::Result<Event>>();
                let mut watcher = match recommended_watcher(tx) {
                    Ok(w) => w,
                    Err(e) => {
                        eprintln!("[watcher] init failed: {}", e);
                        return;
                    }
                };
                for watch_path in &watch_paths {
                    if let Err(e) = watcher.watch(watch_path, RecursiveMode::Recursive) {
                        eprintln!("[watcher] watch {:?} failed: {}", watch_path, e);
                        return;
                    }
                    eprintln!("[watcher] watching {:?}", watch_path);
                }

                let mut last_emit = Instant::now() - Duration::from_secs(1);
                let mut last_config_emit = Instant::now() - Duration::from_secs(1);
                // Debounce tools-pane reloads: defer the emit until 500ms
                // after the last tools-pane event, so a rapid burst of
                // saves coalesces into a single reload (single flash
                // instead of N). Other channels stay immediate.
                let tools_debounce = Duration::from_millis(500);
                let mut pending_tools_since: Option<Instant> = None;
                // Debounce worklist-changed emits: notify-rs produces ~6
                // events per atomic rename + modify of worklist.json
                // (and worklist-history snapshots), and the iframe's
                // worklist-changed listener triggers /__worklist and
                // /__worklist-history/list refetches per event. A 200ms
                // debounce coalesces the cascade into one emit per
                // logical change. Refs #85.
                let worklist_debounce = Duration::from_millis(200);
                let mut pending_worklist_since: Option<Instant> = None;
                let mut hook_fingerprints: HashMap<String, String> = HashMap::new();
                for (rel, path) in [
                    (
                        "app/provider-hooks/claude-worklist-guard.py",
                        proj_root_path.join("app/provider-hooks/claude-worklist-guard.py"),
                    ),
                    (
                        ".claude/hooks/claude-worklist-guard.py",
                        proj_root_path.join(ENHANCE_HOOK_SCRIPT_REL),
                    ),
                    (
                        "app/shell/worklist-guard-codex.py",
                        proj_root_path.join("app/shell/worklist-guard-codex.py"),
                    ),
                ] {
                    if path.exists() {
                        hook_fingerprints.insert(rel.to_string(), file_fingerprint(&path));
                    }
                }
                if let Some(path) = home_dir().map(|h| h.join(ENHANCE_CODEX_HOOK_INSTALL_REL)) {
                    if path.exists() {
                        hook_fingerprints.insert(
                            "codex-worklist-guard.py".to_string(),
                            file_fingerprint(&path),
                        );
                    }
                }
                // issue-342: honor the project's .gitignore directory entries,
                // not just the hardcoded noise dirs. The freeze cause is always
                // a high-frequency write stream into a gitignored SCRATCH DIR
                // (Playwright test-results/, cargo target/) the old four-name
                // list didn't cover, so every artifact dispatched a git-status
                // refresh. Matching gitignored directory names kills it at the
                // source. Root .gitignore, simple single-segment dir entries
                // only; nested .gitignores and glob/negation patterns are a
                // follow-up. Computed once at watcher start — a .gitignore edit
                // is picked up on the next launch.
                fn gitignore_ignored_dir_names(proj_root: &std::path::Path) -> Vec<String> {
                    let mut out: Vec<String> = Vec::new();
                    let Ok(content) = std::fs::read_to_string(proj_root.join(".gitignore")) else {
                        return out;
                    };
                    for raw in content.lines() {
                        let line = raw.trim();
                        if line.is_empty() || line.starts_with('#') || line.starts_with('!') {
                            continue;
                        }
                        // Globs and internal path separators are not the plain
                        // scratch-dir class this targets.
                        if line.contains('*') || line.contains('?') || line.contains('[') {
                            continue;
                        }
                        let seg = line.trim_matches('/');
                        if seg.is_empty() || seg.contains('/') {
                            continue;
                        }
                        if !out.iter().any(|e| e == seg) {
                            out.push(seg.to_string());
                        }
                    }
                    out
                }
                let gitignore_dirs = gitignore_ignored_dir_names(&proj_root_path);
                if bram_trace_enabled() {
                    append_bram_trace_line(
                        &app_handle,
                        "watcher",
                        &format!(
                            "op=gitignore-dirs count={} dirs={}",
                            gitignore_dirs.len(),
                            gitignore_dirs.join(",")
                        ),
                    );
                }
                // issue-342: trailing-edge coalesce for git-status-changed. The
                // 100ms path was tuned for human-speed atomic saves; a bulk
                // change to NON-ignored tracked files can still burst, so emit
                // once when it quiets — riding the recv_timeout wake the way the
                // tools/worklist debounces do. Low-frequency .git-state signals
                // (commits, ref moves) stay immediate below.
                let git_status_debounce = Duration::from_millis(1000);
                let mut pending_git_status_since: Option<Instant> = None;
                // watcher-coalesce-session-jsonl-storm: trailing-edge coalesce
                // for the session-JSONL WEBVIEW cascade (talk-session-changed,
                // subagents-changed, search-index reindex). A subagent's
                // transcript grows on every append during a spec run, and
                // emitting the cascade per append starves the webview (the
                // xmlui freeze: 798 heartbeat-drift with git-status already
                // fixed). Trailing-edge fires the FINAL state after the burst
                // quiets, so unlike the leading-edge debounce removed earlier
                // it does not strand the last write (the isWaitingForAssistant
                // flip). Turn-end detection stays per-event below — only the
                // webview emits are deferred.
                let session_emit_debounce = Duration::from_millis(400);
                let mut pending_session_emit_since: Option<Instant> = None;
                let mut pending_session_emit_paths: Vec<std::path::PathBuf> = Vec::new();
                let mut pending_subagents_emit = false;
                use std::sync::mpsc::RecvTimeoutError;
                loop {
                    let res = rx.recv_timeout(Duration::from_millis(100));
                    // Always check the pending tools emit before processing
                    // the new event — a recv_timeout wake with no event is
                    // the typical trigger for firing a deferred reload.
                    if let Some(since) = pending_tools_since {
                        if since.elapsed() >= tools_debounce {
                            eprintln!("[watcher] change detected, emitting tools-pane-reload (debounced)");
                            // force=false: dev hot-reload, gated by toolsPaneHotReload.
                            emit_or_defer_tools_pane_reload(&app_handle, false);
                            pending_tools_since = None;
                        }
                    }
                    if let Some(since) = pending_worklist_since {
                        if since.elapsed() >= worklist_debounce {
                            eprintln!("[watcher] change detected, emitting worklist-changed (debounced)");
                            emit_replayable_signal(&app_handle, "worklist-changed");
                            // Event-driven indexing: worklist-history files are
                            // written on commit/prune — reindex history now.
                            search_index_request(IndexBucket::History);
                            // state-mirror-items-shadow: this debounce window
                            // has already absorbed every raw event in the
                            // burst, so any maybe_snapshot_worklist /
                            // maybe_enforce_worklist_policy revert for this
                            // change has already run synchronously in an
                            // earlier loop iteration — mirror the settled,
                            // possibly-restored file contents, not a
                            // mid-burst or rejected one.
                            worklist_state_mirror_items(&app_handle, "watcher");
                            pending_worklist_since = None;
                        }
                    }
                    // issue-342: fire the coalesced git-status-changed once the
                    // burst of non-ignored working-tree changes has quieted.
                    if let Some(since) = pending_git_status_since {
                        if since.elapsed() >= git_status_debounce {
                            emit_replayable_signal(&app_handle, "git-status-changed");
                            pending_git_status_since = None;
                        }
                    }
                    // watcher-coalesce-session-jsonl-storm: fire the coalesced
                    // session-activity emits once the append burst has quieted.
                    if let Some(since) = pending_session_emit_since {
                        if since.elapsed() >= session_emit_debounce {
                            if pending_subagents_emit {
                                emit_replayable_signal(&app_handle, "subagents-changed");
                                pending_subagents_emit = false;
                            }
                            if !pending_session_emit_paths.is_empty() {
                                emit_talk_session_changed_for_path_providers(
                                    &app_handle,
                                    &pending_session_emit_paths,
                                    claude_sessions_dir.as_ref(),
                                    codex_sessions_dir.as_ref(),
                                );
                                pending_session_emit_paths.clear();
                                search_index_request(IndexBucket::Sessions);
                            }
                            pending_session_emit_since = None;
                        }
                    }
                    let event = match res {
                        Ok(Ok(ev)) => ev,
                        Ok(Err(_)) => continue,
                        Err(RecvTimeoutError::Timeout) => continue,
                        Err(RecvTimeoutError::Disconnected) => break,
                    };
                    let in_ignored_dir = |p: &std::path::Path| {
                        let igs = [".git", "target", "node_modules", "resources"];
                        p.components().any(|c| {
                            let name = c.as_os_str();
                            igs.iter().any(|ig| name == *ig)
                                || gitignore_dirs.iter().any(|g| name == g.as_str())
                        })
                    };
                    let trace_rel_path = |p: &std::path::Path| {
                        let rel = p
                            .strip_prefix(&proj_root_path)
                            .ok()
                            .map(|r| r.to_string_lossy().replace('\\', "/"))
                            .unwrap_or_else(|| {
                                p.file_name()
                                    .and_then(|n| n.to_str())
                                    .unwrap_or("")
                                    .to_string()
                            });
                        if rel == "resources/bram-traces/bram-trace.log"
                            || is_bram_trace_archive_rel(&rel)
                        {
                            None
                        } else {
                            Some(rel)
                        }
                    };
                    let dispatch_trace_path =
                        || event.paths.iter().find_map(|p| trace_rel_path(p));
                    let is_git_state_path = |p: &std::path::Path| -> bool {
                        let Ok(rel) = p.strip_prefix(&proj_root_path) else {
                            return false;
                        };
                        let parts: Vec<String> = rel
                            .components()
                            .map(|c| c.as_os_str().to_string_lossy().to_string())
                            .collect();
                        if parts.first().map(|s| s.as_str()) != Some(".git") {
                            return false;
                        }
                        matches!(
                            parts.get(1).map(|s| s.as_str()),
                            Some("HEAD") | Some("index") | Some("packed-refs")
                        ) || (parts.get(1).map(|s| s.as_str()) == Some("refs")
                            && parts.get(2).map(|s| s.as_str()) == Some("heads"))
                            || (parts.get(1).map(|s| s.as_str()) == Some("logs")
                                && parts.get(2).map(|s| s.as_str()) == Some("HEAD"))
                    };
                    let hook_target_from_rel = |rel: &str| -> Option<String> {
                        let base = rel
                            .find(".tmp.")
                            .map(|idx| &rel[..idx])
                            .unwrap_or(rel);
                        if base.ends_with("worklist-guard.py")
                            || base.ends_with("worklist-guard-codex.py")
                            || base.ends_with("codex-worklist-guard.py")
                        {
                            Some(base.to_string())
                        } else {
                            None
                        }
                    };
                    let writer_source_from_rel = |rel: &str| -> String {
                        rel.find(".tmp.")
                            .and_then(|idx| rel[idx + 5..].split('.').next())
                            .filter(|pid| !pid.is_empty())
                            .map(|pid| format!("tmp-pid:{}", pid))
                            .unwrap_or_else(|| "unknown".to_string())
                    };
                    let trace_dispatch = |dispatch: &str, fields: &[(&str, String)]| {
                        if !bram_trace_enabled() {
                            return;
                        }
                        let Some(path) = dispatch_trace_path() else {
                            return;
                        };
                        let mut parts = vec![format!("dispatch={}", dispatch), format!("path={}", path)];
                        for (key, value) in fields {
                            parts.push(format!("{}={}", key, value));
                        }
                        append_bram_trace_line(&app_handle, "watcher", &parts.join(" "));
                    };

                    // [watcher] trace: one record per path per notify
                    // event, before any dispatch. Logs project-relative
                    // paths; absolute / outside-project paths fall back
                    // to file_name only so no host filesystem layout
                    // leaks into the log.
                    //
                    // Skip the live trace log and dated trace archives
                    // to avoid self-feeding loop / reload noise: the
                    // live file is written by append_bram_trace_line,
                    // and startup archiving may create
                    // resources/bram-traces/bram-trace-YYYY-MM-DD*.log files.
                    // Neither should emit more watcher trace or reload
                    // behavior. See fix-watcher-trace-self-feeding-loop.
                    if bram_trace_enabled() {
                        let change = notify_event_kind_label(&event.kind);
                        for p in &event.paths {
                            if p.starts_with(&proj_root_path) && in_ignored_dir(p) {
                                continue;
                            }
                            let rel = p
                                .strip_prefix(&proj_root_path)
                                .ok()
                                .map(|r| r.to_string_lossy().replace('\\', "/"))
                                .unwrap_or_else(|| {
                                    p.file_name()
                                        .and_then(|n| n.to_str())
                                        .unwrap_or("")
                                        .to_string()
                                });
                            if rel == "resources/bram-traces/bram-trace.log"
                                || is_bram_trace_archive_rel(&rel)
                            {
                                continue;
                            }
                            append_bram_trace_line(
                                &app_handle,
                                "watcher",
                                &format!("path={} change={} dedup=false", rel, change),
                            );
                        }
                    }

                    if bram_trace_enabled() {
                        let change = notify_event_kind_label(&event.kind);
                        for p in &event.paths {
                            if p.starts_with(&proj_root_path) && in_ignored_dir(p) {
                                continue;
                            }
                            let rel = p
                                .strip_prefix(&proj_root_path)
                                .ok()
                                .map(|r| r.to_string_lossy().replace('\\', "/"))
                                .unwrap_or_else(|| {
                                    p.file_name()
                                        .and_then(|n| n.to_str())
                                        .unwrap_or("")
                                        .to_string()
                                });
                            let Some(target_rel) = hook_target_from_rel(&rel) else {
                                continue;
                            };
                            let target_path = if rel.contains(".tmp.") {
                                let target_name = Path::new(&target_rel)
                                    .file_name()
                                    .and_then(|n| n.to_str())
                                    .unwrap_or("");
                                p.parent()
                                    .map(|parent| parent.join(target_name))
                                    .unwrap_or_else(|| p.to_path_buf())
                            } else {
                                p.to_path_buf()
                            };
                            let pre = hook_fingerprints
                                .get(&target_rel)
                                .cloned()
                                .unwrap_or_else(|| "unknown".to_string());
                            let post = file_fingerprint(&target_path);
                            let post_size = std::fs::metadata(&target_path)
                                .map(|m| m.len())
                                .unwrap_or(0);
                            hook_fingerprints.insert(target_rel.clone(), post.clone());
                            append_bram_trace_line(
                                &app_handle,
                                "hook-write",
                                &format!(
                                    "target={} event_path={} change={} pre={} post={} post_size={} writer_source={}",
                                    target_rel,
                                    rel,
                                    change,
                                    pre,
                                    post,
                                    post_size,
                                    writer_source_from_rel(&rel)
                                ),
                            );
                        }
                    }

                    // subagents-changed: any artifact under a session's
                    // subagents/ dir (agent-*.jsonl appends, meta.json
                    // writes). Emitted BEFORE the session-JSONL branch below
                    // because that branch `continue`s — subagent .jsonl
                    // appends would be swallowed there and never reach the
                    // sessions-list-changed emit, leaving the footer chips
                    // and subagent views stale until the MAIN conversation
                    // next moved (2026-07-05: second chip missing until the
                    // user's next turn). The footer roster, Transcript
                    // subagent viewport, and SubagentPeek refetch on this.
                    let is_subagent_event = event
                        .paths
                        .iter()
                        .any(|p| p.components().any(|c| c.as_os_str() == "subagents"));
                    if is_subagent_event {
                        trace_dispatch("subagents", &[]);
                        // watcher-coalesce: defer to the trailing-edge fire.
                        pending_subagents_emit = true;
                        pending_session_emit_since = Some(Instant::now());
                    }

                    // Session JSONL changes get their own dispatch. The
                    // Transcript / Workspace panes subscribe to
                    // talk-session-changed as the change-signal tick, without
                    // waiting on a fallback poll interval.
                    let is_session_event = event.paths.iter().any(|p| {
                        p.extension().map_or(false, |e| e == "jsonl")
                            && (claude_sessions_dir.as_ref().map_or(false, |sd| p.starts_with(sd))
                                || codex_sessions_dir.as_ref().map_or(false, |sd| p.starts_with(sd)))
                    });
                    if is_session_event {
                        trace_dispatch("session-jsonl", &[]);
                        // [jsonl] trace: ground-truth signal that the
                        // agent is producing structured output. Lets
                        // #78 analysis tell a premature `[turn-end]`
                        // from a real one — a premature fire is
                        // followed within seconds by another `[jsonl]`
                        // line, proving the agent was still working.
                        // One trace line per jsonl path per watcher
                        // event (the filesystem batches at write-flush
                        // granularity, which is the cadence we want).
                        if bram_trace_enabled() {
                            for p in &event.paths {
                                if p.extension().map_or(false, |e| e == "jsonl") {
                                    let name = p
                                        .file_name()
                                        .and_then(|n| n.to_str())
                                        .unwrap_or("");
                                    let size =
                                        std::fs::metadata(p).map(|m| m.len()).unwrap_or(0);
                                    append_bram_trace_line(
                                        &app_handle,
                                        "jsonl",
                                        &format!("file={} bytes={}", name, size),
                                    );
                                }
                            }
                        }
                        // JSONL-driven turn-end detection (#91 follow-up).
                        // Parses each changed JSONL for a Claude
                        // `stop_reason: "end_turn"` last-line marker; if
                        // present and the sentinel is claimed, clears it
                        // directly. More reliable than the PTY-silence
                        // path for cycles where the agent has multi-second
                        // pauses between bursts. The silence-driven path
                        // remains as fallback (gated by
                        // MIN_SILENCE_FOR_SENTINEL_CLEAR_MS); if this
                        // detector fires first, the silence-driven clear
                        // is a no-op because the sentinel is already gone.
                        for p in &event.paths {
                            if p.extension().map_or(false, |e| e == "jsonl") {
                                let mtime_ms = std::fs::metadata(p)
                                    .ok()
                                    .and_then(|md| md.modified().ok())
                                    .and_then(system_time_ms)
                                    .unwrap_or(0);
                                trace_jsonl_detector_handoff(
                                    &app_handle,
                                    "watcher",
                                    p,
                                    mtime_ms,
                                );
                                check_jsonl_for_turn_end(&app_handle, p);
                                // #170 follow-up: when a menu is currently
                                // shown without a signature, the cumulative
                                // recheck schedule (200 / 500 / 1500 / 3000
                                // ms) may still be too tight for very large
                                // tool_use payloads (e.g. `gh issue create`
                                // with multi-KB issue bodies). The watcher
                                // already sees JSONL grow on each Claude
                                // write; piggyback on that here for a
                                // dynamic retry the moment the file changes.
                                try_signature_recheck_on_jsonl_change(&app_handle);
                                // upstream-posttooluse-on-failure: a failed
                                // command's tool_result is the terminal
                                // event CC never sends as a hook — sweep
                                // resolved claims now (no-op when the
                                // queue is empty).
                                janitor_resolved_claims(&app_handle);
                            }
                        }
                        // watcher-coalesce-session-jsonl-storm: the webview
                        // emit + reindex are deferred to the trailing-edge fire
                        // at the top of the loop. A leading-edge debounce here
                        // was removed once because it dropped the FINAL write's
                        // emit (wedging the spinner) — trailing-edge fires that
                        // final emit after the burst quiets, so it coalesces the
                        // storm WITHOUT the wedge. The per-event turn-end
                        // detection above is unaffected.
                        pending_session_emit_paths = event.paths.clone();
                        pending_session_emit_since = Some(Instant::now());
                        continue;
                    }

                    // enhance-status (agent-setup state) changes when any
                    // of these files are touched. The tools-pane
                    // Main.xmlui listens for `enhance-status-changed` and
                    // refetches /__enhance/status, replacing the prior
                    // 2-second poll that ran while the user was typing.
                    // Not a `continue` — the regular tools-pane reload
                    // still fires on its normal path below.
                    let is_enhance_event = event.paths.iter().any(|p| {
                        let name = p.file_name().and_then(|n| n.to_str()).unwrap_or("");
                        let in_claude_dir = p.components().any(|c| c.as_os_str() == ".claude");
                        let in_current_agent = current_agent_dir
                            .as_ref()
                            .map_or(false, |ah| p.starts_with(ah));
                        let in_bram_dir = bram_dir.as_ref().map_or(false, |bd| p.starts_with(bd));
                        name == "CLAUDE.md"
                            || name == "AGENTS.md"
                            || (in_claude_dir
                                && (name == "settings.json"
                                    || name == "settings.local.json"
                                    || name == "claude-worklist-guard.py"
                                    // legacy generic name: still watched
                                    // through the #217 transition.
                                    || name == "worklist-guard.py"))
                            // issue-221-skill-launcher: refresh the Skills list
                            // when a .claude/skills/**/SKILL.md changes.
                            || (in_claude_dir
                                && p.components().any(|c| c.as_os_str() == "skills"))
                            || in_current_agent
                            || in_bram_dir
                    });
                    if is_enhance_event {
                        trace_dispatch("enhance-status", &[]);
                        emit_replayable_signal(&app_handle, "enhance-status-changed");
                    }

                    // sessions-list-changed: any mutation under either
                    // Claude or Codex sessions dir — broader than
                    // talk-session-changed (which is JSONL-write-only).
                    // Sessions.xmlui listens for this to refetch its
                    // list (renames, deletes, new sessions all surface).
                    let is_sessions_list_event = event.paths.iter().any(|p| {
                        claude_sessions_dir
                            .as_ref()
                            .map_or(false, |sd| p.starts_with(sd))
                            || codex_sessions_dir
                                .as_ref()
                                .map_or(false, |sd| p.starts_with(sd))
                    });
                    if is_sessions_list_event {
                        trace_dispatch("sessions-list", &[]);
                        emit_replayable_signal(&app_handle, "sessions-list-changed");
                    }

                    // worklist-changed: resources/worklist.json, any draft
                    // file, or anything under resources/worklist-history/. Workspace
                    // refetches its DataSources on this.
                    let is_worklist_change = event.paths.iter().any(|p| {
                        let in_resources = p.components().any(|c| c.as_os_str() == "resources");
                        let file = p.file_name().and_then(|n| n.to_str()).unwrap_or("");
                        let in_history = p
                            .components()
                            .any(|c| c.as_os_str() == "worklist-history");
                        let in_drafts = p
                            .components()
                            .any(|c| c.as_os_str() == "worklist-drafts");
                        in_resources && (file == "worklist.json" || in_history || in_drafts)
                    });
                    if is_worklist_change {
                        trace_dispatch("skip", &[("reason", "worklist-event".to_string())]);
                        // Defer the emit; pending_worklist_since either
                        // starts a fresh 200 ms window or rolls forward
                        // on a continuing burst. The loop's wake check
                        // above drains it when the window elapses. Refs
                        // #85 worklist-watcher-debounce.
                        pending_worklist_since = Some(Instant::now());
                    }

                    // feedback-history-changed: anything under
                    // resources/feedback-history/. The Feedback tab's
                    // DataSource refetches on this. Promotion is rare
                    // (once per iterate cycle), so no debounce needed.
                    let is_feedback_history_change = event.paths.iter().any(|p| {
                        p.components().any(|c| c.as_os_str() == "feedback-history")
                            && p.components().any(|c| c.as_os_str() == "resources")
                    });
                    if is_feedback_history_change {
                        trace_dispatch("feedback-history", &[]);
                        emit_replayable_signal(&app_handle, "feedback-history-changed");
                    }

                    // feedback-drafts-changed: anything under
                    // resources/feedback-drafts/. The Transcript's feedback-map
                    // DataSource refetches on this so iterate feedback appears
                    // live — drafts are NOT promoted to history on a plain test
                    // iterate, so feedback-history-changed alone wouldn't cover
                    // them.
                    let is_feedback_drafts_change = event.paths.iter().any(|p| {
                        p.components().any(|c| c.as_os_str() == "feedback-drafts")
                            && p.components().any(|c| c.as_os_str() == "resources")
                    });
                    if is_feedback_drafts_change {
                        trace_dispatch("feedback-drafts", &[]);
                        emit_replayable_signal(&app_handle, "feedback-drafts-changed");
                    }

                    // Codex filesystem lifecycle drain (#130). When Codex
                    // writes resources/.worklist-intent.json, dispatch it
                    // through the same handlers the loopback routes use and
                    // write resources/.worklist-result.json. Fires on
                    // create/modify; the drain reads-then-deletes the intent
                    // file, so duplicate events in one notify burst no-op.
                    let is_intent_event = event.paths.iter().any(|p| {
                        p.file_name().and_then(|n| n.to_str()) == Some(".worklist-intent.json")
                            && p.components().any(|c| c.as_os_str() == "resources")
                    });
                    if is_intent_event
                        && matches!(event.kind, EventKind::Modify(_) | EventKind::Create(_))
                    {
                        trace_dispatch("intent-drain", &[]);
                        drain_worklist_intent(&app_handle);
                    }

                    // Git state changes often happen entirely under .git
                    // (empty commits, branch switches, fetches). Emit the
                    // data refresh event before the ignored-dir skip below.
                    let is_git_state_event = event.paths.iter().any(|p| is_git_state_path(p));
                    if is_git_state_event {
                        trace_dispatch("git-status", &[("source", ".git".to_string())]);
                        emit_replayable_signal(&app_handle, "git-status-changed");
                        // Event-driven indexing: a commit / ref move is a real
                        // change signal — reindex commits now instead of polling.
                        search_index_request(IndexBucket::Commits);
                    }

                    // git-status-changed: any project file change that's
                    // not in the ignored directories (hardcoded noise dirs +
                    // the project's .gitignore dir entries, issue-342). Commits
                    // refetches its log. Coalesced by the trailing-edge
                    // git-status debounce above, not emitted per event.
                    let is_git_status_event = event.paths.iter().any(|p| {
                        p.starts_with(&proj_root_path) && !in_ignored_dir(p)
                    });
                    if is_git_status_event {
                        trace_dispatch("git-status", &[]);
                        // issue-342: defer to the trailing-edge debounce above
                        // instead of emitting per event.
                        pending_git_status_since = Some(Instant::now());
                    }

                    // .bram.json gets its own dispatch: we have to
                    // process it on any event kind (editors atomic-save via
                    // rename, which arrives as Create or Remove rather than
                    // Modify), and its handler may need to respawn the
                    // project server before reloading the iframe.
                    let is_config_event = event.paths.iter().any(|p| {
                        is_project_config_path(&p)
                    });
                    if is_config_event {
                        if last_config_emit.elapsed() < Duration::from_millis(300) {
                            trace_dispatch("skip", &[("reason", "config-debounce-300ms".to_string())]);
                            continue;
                        }
                        last_config_emit = Instant::now();
                        trace_dispatch("config-reload", &[]);
                        eprintln!("[project-config] change detected");
                        handle_project_config_reload(&app_handle, &proj_root_path);
                        continue;
                    }

                    if !matches!(
                        event.kind,
                        EventKind::Modify(_) | EventKind::Create(_)
                    ) {
                        trace_dispatch("skip", &[("reason", "event-kind".to_string())]);
                        continue;
                    }
                    // Worklist history capture. Worklist writes are otherwise
                    // skipped by the ignored-resources rule below (they
                    // shouldn't reload the iframe — the DataSource polls).
                    // Detect them here, snapshot the prior contents, then
                    // fall through to the normal skip.
                    let is_worklist_event = event.paths.iter().any(|p| {
                        let in_resources = p.components().any(|c| c.as_os_str() == "resources");
                        let in_drafts = p
                            .components()
                            .any(|c| c.as_os_str() == "worklist-drafts");
                        in_resources && (p.ends_with("worklist.json") || in_drafts)
                    });
                    if is_worklist_event {
                        maybe_snapshot_worklist(&app_handle);
                    }
                    // Skip events whose paths are entirely inside noisy or
                    // data-only directories. resources/ is data the DataSource
                    // polls; target/, .git/, node_modules/ are build/VCS noise.
                    if event.paths.iter().all(|p| {
                        p.starts_with(&proj_root_path) && in_ignored_dir(p)
                    }) {
                        trace_dispatch("skip", &[("reason", "ignored-dir".to_string())]);
                        continue;
                    }
                    // Editors often write twice (atomic save). Debounce 100ms.
                    if last_emit.elapsed() < Duration::from_millis(100) {
                        trace_dispatch("skip", &[("reason", "debounce-100ms".to_string())]);
                        continue;
                    }
                    last_emit = Instant::now();
                    // Classify: any path under a tools_pane_paths root → tools event.
                    // Otherwise (paths only under proj_root) → right-pane-only event.
                    // Skip doc-only changes (e.g. conventions.md edits)
                    // from triggering a tools-pane-reload. They don't run
                    // code; the rebuild would only churn live UI state.
                    let is_tools_event = event.paths.iter().any(|p| {
                        let is_doc = p.extension().map_or(false, |e| e == "md");
                        !is_doc && tools_pane_paths.iter().any(|tp| p.starts_with(tp))
                    });
                    if is_tools_event {
                        trace_dispatch(
                            "tools-pane",
                            &[("deferred", pending_tools_since.is_some().to_string())],
                        );
                        // Defer the emit; pending_tools_since either starts
                        // the debounce window or resets it on burst writes.
                        pending_tools_since = Some(Instant::now());
                    } else {
                        trace_dispatch("right-pane", &[]);
                        eprintln!("[watcher] change detected, emitting right-pane-reload");
                        trace_emit_signal(&app_handle, "right-pane-reload");
                        let _ = app_handle.emit("right-pane-reload", ());
                    }
                }
            });

            Ok(())
        })
        // issue-341: reap the target-app server when the main window goes
        // away — the quit path that skipped ExitRequested (Walt's clean
        // menu quit) still destroys the window first.
        .on_window_event(|window, event| {
            if matches!(event, tauri::WindowEvent::Destroyed) && window.label() == "main" {
                kill_spawned_server_on_close(&window.app_handle().clone());
            }
        })
        .build(tauri::generate_context!())
        .expect("error while building tauri application")
        .run(|app, event| {
            if let tauri::RunEvent::ExitRequested { .. } = event {
                {
                    let state = app.state::<WhisperState>();
                    let mut guard = state.0.lock().unwrap();
                    if let Some(mut child) = guard.take() {
                        let started = std::time::Instant::now();
                        let pid = child.id();
                        let kill_result = child.kill();
                        whisper_trace(
                            app,
                            &format!(
                                "kill phase=child-kill pid={} ok={} reason=app-exit",
                                pid,
                                kill_result.is_ok()
                            ),
                        );
                        let wait_started = std::time::Instant::now();
                        let wait_result = child.wait();
                        whisper_trace(
                            app,
                            &format!(
                                "kill phase=wait pid={} ok={} elapsed_ms={} reason=app-exit",
                                pid,
                                wait_result.is_ok(),
                                wait_started.elapsed().as_millis()
                            ),
                        );
                        whisper_trace(
                            app,
                            &format!(
                                "kill phase=done pid={} total_elapsed_ms={} reason=app-exit",
                                pid,
                                started.elapsed().as_millis()
                            ),
                        );
                    }
                }
                {
                    let state = app.state::<SpawnedServerState>();
                    let mut guard = state.0.lock().unwrap();
                    if let Some(mut spawned) = guard.take() {
                        let pid = spawned.child.id();
                        // issue-341: group kill + sidecar cleanup, not a
                        // bare pid kill — compound sh -c commands leave the
                        // real server as a grandchild.
                        kill_server_group(pid, project_root(Some(app)).as_deref());
                        let _ = spawned.child.wait();
                        eprintln!("[server] op=exit-kill pid={} via=exit-requested", pid);
                        append_bram_trace_line(
                            app,
                            "server",
                            &format!("op=exit-kill pid={} via=exit-requested", pid),
                        );
                    }
                }
            }
        });
}

// issue-341: belt for quit paths that bypass RunEvent::ExitRequested —
// Walt's clean menu quit orphaned the child even though the exit-requested
// kill existed, so the main window's destruction also reaps. Idempotent
// with the exit-requested path: whichever fires first takes the child.
fn kill_spawned_server_on_close<R: tauri::Runtime>(app: &AppHandle<R>) {
    let state = app.state::<SpawnedServerState>();
    let mut guard = state.0.lock().unwrap();
    if let Some(mut spawned) = guard.take() {
        let pid = spawned.child.id();
        kill_server_group(pid, project_root(Some(app)).as_deref());
        let _ = spawned.child.wait();
        eprintln!("[server] op=exit-kill pid={} via=window-destroyed", pid);
        append_bram_trace_line(
            app,
            "server",
            &format!("op=exit-kill pid={} via=window-destroyed", pid),
        );
    }
}

#[cfg(test)]
mod worklist_change_projection_tests {
    use super::{worklist_change_activity_for, WorklistChangeIndex};
    use std::collections::HashMap;

    fn idx(pairs: &[(&str, &str, i64, i64, i64)]) -> WorklistChangeIndex {
        let mut status_by_path = HashMap::new();
        let mut counts = HashMap::new();
        let mut hunks_by_path = HashMap::new();
        for (path, status, a, r, h) in pairs {
            let st: &'static str = match *status {
                "new" => "new",
                "deleted" => "deleted",
                _ => "modified",
            };
            status_by_path.insert((*path).to_string(), st);
            counts.insert((*path).to_string(), (*a, *r));
            hunks_by_path.insert((*path).to_string(), *h);
        }
        WorklistChangeIndex {
            root: std::env::temp_dir(),
            status_by_path,
            counts,
            hunks_by_path,
            diff_by_path: HashMap::new(),
            spawns: 0,
        }
    }

    fn field(v: &serde_json::Value, k: &str) -> i64 {
        v.get(k).and_then(|x| x.as_i64()).unwrap_or(-1)
    }

    #[test]
    fn an_item_sees_only_its_own_paths_in_a_shared_index() {
        // issue-323's whole safety claim: the index is scoped to the union of
        // every item's paths, and projection is by exact path equality, so a
        // neighbour's changes cannot leak into this item's numbers.
        let i = idx(&[
            ("mine.rs", "modified", 10, 2, 3),
            ("theirs.rs", "modified", 999, 999, 99),
        ]);
        let (_, sum) = worklist_change_activity_for(&i, &["mine.rs".to_string()]).unwrap();
        assert_eq!(field(&sum, "added"), 10);
        assert_eq!(field(&sum, "removed"), 2);
        assert_eq!(
            field(&sum, "hunks"),
            3,
            "neighbour hunks must not be summed"
        );
        assert_eq!(field(&sum, "changed"), 1);
        assert_eq!(field(&sum, "total"), 1);
    }

    #[test]
    fn hunks_sum_across_an_items_own_files() {
        let i = idx(&[
            ("a.rs", "modified", 1, 1, 2),
            ("b.rs", "modified", 3, 0, 5),
            ("elsewhere.rs", "modified", 7, 7, 7),
        ]);
        let files = vec!["a.rs".to_string(), "b.rs".to_string()];
        let (_, sum) = worklist_change_activity_for(&i, &files).unwrap();
        assert_eq!(field(&sum, "hunks"), 7, "2 + 5, not 14");
        assert_eq!(field(&sum, "added"), 4);
        assert_eq!(field(&sum, "changed"), 2);
    }

    #[test]
    fn paths_absent_from_the_index_read_as_unchanged() {
        let i = idx(&[("other.rs", "modified", 5, 5, 5)]);
        let files = vec!["clean.rs".to_string()];
        let (rows, sum) = worklist_change_activity_for(&i, &files).unwrap();
        assert_eq!(field(&sum, "changed"), 0);
        assert_eq!(
            field(&sum, "total"),
            1,
            "the plan denominator still counts it"
        );
        assert_eq!(
            sum.get("diskLabel").and_then(|v| v.as_str()),
            Some("no changes yet")
        );
        assert_eq!(
            rows[0].get("status").and_then(|v| v.as_str()),
            Some("unchanged")
        );
    }

    #[test]
    fn an_empty_file_list_projects_to_none() {
        let i = idx(&[("x.rs", "modified", 1, 1, 1)]);
        assert!(worklist_change_activity_for(&i, &[]).is_none());
    }
}

#[cfg(test)]
mod claim_interval_tests {
    use super::capture_claim_tree;
    use std::path::PathBuf;
    use std::process::Command;

    fn git(root: &PathBuf, args: &[&str]) -> String {
        let out = Command::new("git")
            .current_dir(root)
            .args(args)
            .output()
            .expect("git");
        String::from_utf8_lossy(&out.stdout).trim().to_string()
    }

    fn scratch(name: &str) -> PathBuf {
        let d =
            std::env::temp_dir().join(format!("bram-claimtest-{}-{}", name, std::process::id()));
        let _ = std::fs::remove_dir_all(&d);
        std::fs::create_dir_all(&d).unwrap();
        git(&d, &["init", "-q", "."]);
        git(&d, &["config", "user.email", "t@t"]);
        git(&d, &["config", "user.name", "t"]);
        std::fs::write(d.join("tracked.txt"), "base\n").unwrap();
        git(&d, &["add", "-A"]);
        git(&d, &["commit", "-qm", "base"]);
        d
    }

    // The one property whose violation would corrupt a user's uncommitted
    // work, so it is asserted rather than assumed: capturing must leave the
    // worktree and the index byte-identical.
    #[test]
    fn capture_does_not_disturb_worktree_or_index() {
        let root = scratch("invariance");
        std::fs::write(root.join("tracked.txt"), "base\nmodified\n").unwrap();
        std::fs::write(root.join("untracked.txt"), "new\n").unwrap();
        let before_status = git(&root, &["status", "--porcelain"]);
        let before_body = std::fs::read_to_string(root.join("tracked.txt")).unwrap();

        assert!(capture_claim_tree(&root).is_some(), "capture must succeed");

        assert_eq!(before_status, git(&root, &["status", "--porcelain"]));
        assert_eq!(
            before_body,
            std::fs::read_to_string(root.join("tracked.txt")).unwrap()
        );
        let _ = std::fs::remove_dir_all(&root);
    }

    // `git stash create` omits untracked files, which would make file
    // CREATION unattributable. The temp-index capture must not.
    #[test]
    fn capture_includes_untracked_and_survives_clean_tree() {
        let root = scratch("untracked");
        let clean = capture_claim_tree(&root).expect("clean tree still yields a tree");
        assert_eq!(clean, git(&root, &["rev-parse", "HEAD^{tree}"]));

        std::fs::write(root.join("created.txt"), "brand new\n").unwrap();
        let tree = capture_claim_tree(&root).expect("capture");
        let listed = git(&root, &["ls-tree", "-r", "--name-only", &tree]);
        assert!(
            listed.contains("created.txt"),
            "untracked file must be captured, got: {listed}"
        );
        let _ = std::fs::remove_dir_all(&root);
    }

    // The whole point: the diff between two boundaries is exactly the work
    // done in that interval, and none of the previous holder's.
    #[test]
    fn interval_between_two_boundaries_isolates_the_second_items_work() {
        let root = scratch("interval");
        std::fs::write(root.join("tracked.txt"), "base\nfrom A\n").unwrap();
        let a = capture_claim_tree(&root).expect("A");

        std::fs::write(root.join("tracked.txt"), "base\nfrom A\nfrom B\n").unwrap();
        std::fs::write(root.join("b-only.txt"), "b\n").unwrap();
        let b = capture_claim_tree(&root).expect("B");

        let names = git(&root, &["diff", "--name-only", &a, &b]);
        assert!(names.contains("b-only.txt"), "B's new file, got: {names}");
        let patch = git(&root, &["diff", &a, &b, "--", "tracked.txt"]);
        assert!(patch.contains("+from B"), "B's hunk missing: {patch}");
        assert!(
            !patch.contains("+from A"),
            "A's work must NOT appear in the A..B interval: {patch}"
        );
        let _ = std::fs::remove_dir_all(&root);
    }
}

#[cfg(test)]
mod claim_interval_prune_tests {
    use super::{claim_intervals_partition, GhostOwnerIndex};
    use serde_json::json;
    use std::collections::HashSet;

    fn rec(r: &str, ids: &[&str]) -> serde_json::Value {
        json!({"ref": r, "ids": ids, "atMs": 1, "kind": "approved", "tree": "t"})
    }
    fn live(ids: &[&str]) -> HashSet<String> {
        ids.iter().map(|s| s.to_string()).collect()
    }

    // The hazard the rule exists for: r2 begins B's interval but ENDS A's, so
    // while A is live it must survive even though B is gone.
    #[test]
    fn a_boundary_bounding_a_live_interval_survives() {
        let ivs = vec![rec("refs/a", &["A"]), rec("refs/b", &["B"])];
        let (keep, retire) = claim_intervals_partition(&ivs, &live(&["A"]));
        assert!(
            retire.is_empty(),
            "nothing retirable while A lives: {retire:?}"
        );
        assert_eq!(keep.len(), 2);
    }

    #[test]
    fn both_neighbours_dead_retires_the_boundary() {
        let ivs = vec![
            rec("refs/a", &["A"]),
            rec("refs/b", &["B"]),
            rec("refs/c", &["C"]),
        ];
        // Only C survives: refs/a has no live predecessor and a dead owner;
        // refs/b is dead-owned but PRECEDES C's boundary -- still, refs/c is
        // the one that bounds C, so refs/b is retirable and refs/c is not.
        let (_, retire) = claim_intervals_partition(&ivs, &live(&["C"]));
        assert_eq!(retire, vec!["refs/a".to_string(), "refs/b".to_string()]);
    }

    // Even with nothing live, the newest boundary survives: it is the base of
    // the open interval, so retiring it would leave the next claim's work with
    // nothing to diff against.
    #[test]
    fn empty_board_retires_everything_except_the_open_base() {
        let ivs = vec![rec("refs/a", &["A"]), rec("refs/b", &["B"])];
        let (keep, retire) = claim_intervals_partition(&ivs, &live(&[]));
        assert_eq!(retire, vec!["refs/a".to_string()]);
        assert_eq!(keep.len(), 1, "the open interval's base must survive");
    }

    // The live regression: a commit-gate click writes a boundary owned by the
    // very item the commit then prunes. Both adjacency conditions are
    // satisfied, and retiring it anyway emptied the store completely.
    #[test]
    fn committing_the_last_claimant_does_not_empty_the_store() {
        let ivs = vec![
            rec("refs/a", &["panel"]),
            rec("refs/b", &["hygiene"]),
            rec("refs/c", &["panel"]),
        ];
        let (keep, retire) = claim_intervals_partition(&ivs, &live(&[]));
        assert_eq!(retire, vec!["refs/a".to_string(), "refs/b".to_string()]);
        assert_eq!(keep.len(), 1);
        assert_eq!(
            keep[0].get("ref").and_then(|v| v.as_str()),
            Some("refs/c"),
            "the newest boundary is the open interval's base"
        );
    }

    #[test]
    fn a_single_record_is_always_kept() {
        let ivs = vec![rec("refs/only", &["gone"])];
        let (keep, retire) = claim_intervals_partition(&ivs, &live(&[]));
        assert!(retire.is_empty());
        assert_eq!(keep.len(), 1);
    }

    // A multi-id claim keeps its boundary while ANY of its items survives.
    #[test]
    fn multi_id_claim_survives_on_one_live_member() {
        let ivs = vec![rec("refs/a", &["A", "B"])];
        let (keep, retire) = claim_intervals_partition(&ivs, &live(&["B"]));
        assert!(retire.is_empty());
        assert_eq!(keep.len(), 1);
    }

    // A record naming no ref cannot be retired from git; keeping it is the
    // safe side, since dropping it would orphan whatever it was meant to name.
    #[test]
    fn record_without_a_ref_is_kept_not_silently_dropped() {
        let ivs = vec![serde_json::json!({"ids": ["A"]})];
        let (keep, retire) = claim_intervals_partition(&ivs, &live(&[]));
        assert!(retire.is_empty());
        assert_eq!(keep.len(), 1);
    }

    fn ghost_idx(live: &[&str]) -> GhostOwnerIndex {
        GhostOwnerIndex {
            live: live.iter().map(|s| s.to_string()).collect(),
        }
    }

    #[test]
    fn live_owner_passes_through_untouched() {
        let idx = ghost_idx(&["A"]);
        assert_eq!(idx.strip_ghost(Some("A".into())), (Some("A".into()), None));
        assert_eq!(idx.strip_ghost(None), (None, None));
    }

    // ghost-reassignment-inflates-totals: a departed owner strips to unowned
    // EVERYWHERE — never reassigned to a surviving item. Both cleverer
    // resolutions lied in production the day they shipped: stale ghost
    // patches broke staging ("patch does not apply" ×3), and display-only
    // reassignment inflated a survivor's totals with already-committed
    // content (+802 against a true ~+290).
    #[test]
    fn ghost_strips_to_unowned() {
        let idx = ghost_idx(&["B"]);
        assert_eq!(
            idx.strip_ghost(Some("dead".into())),
            (None, Some("dead".into()))
        );
    }
}

#[cfg(test)]
mod claim_attribution_tests {
    use super::{apply_attr_hunks, attr_replay_line_offset, attr_runs, parse_attr_diff};

    // attribution-run-line-offset-in-views: the tripwire's arithmetic. The
    // #324/trace-vocabulary shape was a run rendered at line 56 while the
    // real diff sat at 86 — a +30 offset the replay length would have exposed.
    #[test]
    fn replay_offset_detects_length_divergence() {
        // Healthy: base 50, net +36, file 86 → no offset.
        assert_eq!(attr_replay_line_offset(50, 36, 86), None);
        // The live shape: replay reconstructs 56, file is 86 → +30.
        assert_eq!(attr_replay_line_offset(50, 6, 86), Some(30));
        // Shrink case: replay 100, file 90 → -10.
        assert_eq!(attr_replay_line_offset(100, 0, 90), Some(-10));
        // Net that would underflow clamps at 0, not a panic.
        assert_eq!(attr_replay_line_offset(3, -10, 0), None);
        assert_eq!(attr_replay_line_offset(3, -10, 5), Some(5));
    }

    fn owners(n: usize) -> Vec<Option<String>> {
        vec![None; n]
    }
    fn ids(o: &[Option<String>]) -> String {
        o.iter()
            .map(|x| x.as_deref().unwrap_or("."))
            .collect::<Vec<_>>()
            .join("")
    }

    #[test]
    fn parses_path_and_hunk_start() {
        let d =
            "diff --git a/f.md b/f.md\n--- a/f.md\n+++ b/f.md\n@@ -3,2 +3,3 @@ ctx\n x\n+new\n y\n";
        let m = parse_attr_diff(d);
        let h = &m["f.md"];
        assert_eq!(h.len(), 1);
        assert_eq!(h[0].old_start, 3);
        assert_eq!(h[0].lines.len(), 3);
    }

    #[test]
    fn insertion_owns_only_the_added_lines() {
        let mut o = owners(4);
        let m = parse_attr_diff("+++ b/f\n@@ -2,1 +2,3 @@\n a\n+X\n+Y\n");
        apply_attr_hunks(&mut o, &m["f"], "A");
        assert_eq!(ids(&o), "..AA..");
    }

    // attribution-run-line-offset-in-views: a DELETED file's target line is
    // `+++ /dev/null`, so its `-` hunks must attribute to the file named by
    // `diff --git`, NOT bleed onto the preceding file. The live bug: a delete
    // right after a modify put the deletions on the modified file, shifting
    // every run and rendering the change as "no item".
    #[test]
    fn deleted_file_hunks_do_not_bleed_onto_preceding_file() {
        let d = "diff --git a/keep.md b/keep.md\n--- a/keep.md\n+++ b/keep.md\n\
                 @@ -1,1 +1,1 @@\n-old\n+new\n\
                 diff --git a/gone.txt b/gone.txt\ndeleted file mode 100644\n\
                 --- a/gone.txt\n+++ /dev/null\n@@ -1,3 +0,0 @@\n-a\n-b\n-c\n";
        let m = parse_attr_diff(d);
        // keep.md gets ONLY its own +1/-1, not gone.txt's three deletions.
        let keep_net: isize = m["keep.md"]
            .iter()
            .flat_map(|h| h.lines.iter())
            .map(|(c, _)| match c {
                '+' => 1,
                '-' => -1,
                _ => 0,
            })
            .sum();
        assert_eq!(keep_net, 0, "keep.md must not absorb gone.txt's deletions");
        assert!(
            m.contains_key("gone.txt"),
            "the deletion attributes to gone.txt"
        );
    }

    // fix-attribution-run-line-offset: the chain-replay must place a sole
    // claimant's added lines at their TRUE positions even when the base tree
    // is old and an earlier interval grew the file (a committed resize). This
    // is the adversarial shape #327's interval staging depends on; it
    // reproduces (in-repo, no git needed) the scratch case that proved the
    // algorithm sound after the 2026-09-03 field anomaly. base is 40 lines;
    // item-old inserts 5 after line 5 (file → 45); item-mid touches nothing;
    // prose edits near the end. Prose's run must sit where prose actually
    // edited, not shifted by the intervening growth.
    fn hunks(diff: &str) -> Vec<super::AttrHunk> {
        super::parse_attr_diff(diff)["f"].clone()
    }
    #[test]
    fn attribution_replay_survives_intervening_resize() {
        let base_n = 40;
        let step_old = (
            Some("item-old".to_string()),
            hunks("+++ b/f\n@@ -5,1 +5,6 @@\n line5\n+g1\n+g2\n+g3\n+g4\n+g5\n"),
        );
        // item-mid touches the file in neither direction; it simply is not a
        // step for this path (mirrors an empty interval diff).
        let step_prose = (
            Some("prose".to_string()),
            hunks("+++ b/f\n@@ -41,1 +41,3 @@\n line38\n+edit1\n+edit2\n"),
        );
        let runs = super::attribution_runs_for_path(base_n, &[step_old, step_prose]);
        // item-old owns the 5 grown lines at 6..10; prose owns its 2 edits at
        // the grown position 42..43 — not shifted low.
        assert_eq!(runs.len(), 2);
        assert_eq!(runs[0]["itemId"], "item-old");
        assert_eq!(runs[0]["startLine"], 6);
        assert_eq!(runs[0]["endLine"], 10);
        assert_eq!(runs[1]["itemId"], "prose");
        assert_eq!(runs[1]["startLine"], 42);
        assert_eq!(runs[1]["endLine"], 43);
    }

    // joint-interval-files-disambiguation: per-(interval, path) resolution.
    #[test]
    fn joint_interval_resolves_by_sole_declarer_and_stays_joint_otherwise() {
        use super::{resolve_interval_path_owner, IntervalPathOwner};
        let mut declared = std::collections::HashMap::new();
        declared.insert("a".to_string(), vec!["src/lib.rs".to_string()]);
        declared.insert(
            "b".to_string(),
            vec!["docs/x.md".to_string(), "docs/".to_string()],
        );
        let ids = vec!["a".to_string(), "b".to_string()];
        // Declared by exactly one of the joint ids → that id.
        assert!(matches!(
            resolve_interval_path_owner(&ids, "src/lib.rs", &declared),
            IntervalPathOwner::Single(ref s) if s == "a"
        ));
        // Directory declaration covers nested paths.
        assert!(matches!(
            resolve_interval_path_owner(&ids, "docs/deep/y.md", &declared),
            IntervalPathOwner::Single(ref s) if s == "b"
        ));
        // Worktree-prefixed twin resolves like the real path (#309).
        assert!(matches!(
            resolve_interval_path_owner(&ids, ".claude/worktrees/agent-a/src/lib.rs", &declared),
            IntervalPathOwner::Single(ref s) if s == "a"
        ));
        // Declared by NONE of them: the window's id-set is still the honest
        // candidate list ("made while a+b were claimed"), so it stays joint
        // rather than collapsing to bare unowned.
        match resolve_interval_path_owner(&ids, "README.md", &declared) {
            IntervalPathOwner::Joint(set) => assert_eq!(set, ids),
            _ => panic!("zero-declarer multi-id path must stay with the joint set"),
        }
        // Declared by both → joint, the honest shared state.
        declared.insert("a".to_string(), vec!["docs/x.md".to_string()]);
        match resolve_interval_path_owner(&ids, "docs/x.md", &declared) {
            IntervalPathOwner::Joint(set) => assert_eq!(set, ids),
            _ => panic!("multi-declarer path must stay joint"),
        }
        // Single-id claims resolve as before, declaration or not.
        assert!(matches!(
            resolve_interval_path_owner(&ids[..1], "anything.txt", &declared),
            IntervalPathOwner::Single(ref s) if s == "a"
        ));
    }

    // A joint owner rides the marker encoding through the replay and expands
    // into an itemIds run — never an itemId, never silently dropped.
    #[test]
    fn joint_marker_expands_to_item_ids_run() {
        let sep = super::JOINT_RUN_SEP;
        let joint = format!("{}a{}b", sep, sep);
        let step = (Some(joint), hunks("+++ b/f\n@@ -1,0 +1,2 @@\n+j1\n+j2\n"));
        let runs = super::attribution_runs_for_path(3, &[step]);
        assert_eq!(runs.len(), 1);
        assert!(runs[0].get("itemId").is_none());
        assert_eq!(runs[0]["itemIds"], serde_json::json!(["a", "b"]));
        assert_eq!(runs[0]["startLine"], 1);
        assert_eq!(runs[0]["endLine"], 2);
    }

    // The regression this whole design exists to avoid: identical line CONTENT
    // owned by different claimants. A content-keyed lookup collapses these.
    #[test]
    fn duplicate_lines_are_attributed_by_position_not_content() {
        let mut o = owners(2);
        // A inserts a blank + fence at the top...
        let a = parse_attr_diff("+++ b/f\n@@ -1,0 +1,2 @@\n+\n+```\n");
        apply_attr_hunks(&mut o, &a["f"], "A");
        // ...C inserts an IDENTICAL blank + fence further down.
        let c = parse_attr_diff("+++ b/f\n@@ -4,0 +4,2 @@\n+\n+```\n");
        apply_attr_hunks(&mut o, &c["f"], "C");
        assert_eq!(ids(&o), "AA.CC.");
    }

    // Four claimants, three hunks: two edited ADJACENT regions and git merged
    // them. Whole-hunk attribution fails here; the replay must not.
    #[test]
    fn adjacent_claimants_split_within_one_region() {
        let mut o = owners(2);
        let a = parse_attr_diff("+++ b/f\n@@ -1,0 +1,3 @@\n+a1\n+a2\n+a3\n");
        apply_attr_hunks(&mut o, &a["f"], "A");
        let d = parse_attr_diff("+++ b/f\n@@ -4,0 +4,2 @@\n+d1\n+d2\n");
        apply_attr_hunks(&mut o, &d["f"], "D");
        assert_eq!(ids(&o), "AAADD..");
        let runs = attr_runs(&o);
        assert_eq!(runs.len(), 2);
        assert_eq!(runs[0]["itemId"], "A");
        assert_eq!(runs[0]["endLine"], 3);
        assert_eq!(runs[1]["itemId"], "D");
        assert_eq!(runs[1]["startLine"], 4);
        assert_eq!(runs[1]["endLine"], 5);
    }

    #[test]
    fn deletions_remove_ownership_and_shift_later_hunks() {
        let mut o = owners(5);
        let a = parse_attr_diff("+++ b/f\n@@ -2,2 +2,1 @@\n-old\n+new\n");
        apply_attr_hunks(&mut o, &a["f"], "A");
        assert_eq!(ids(&o), ".A...");
    }

    // Unowned lines are a state, not a gap: they must not appear as runs, and
    // must not be folded into a neighbouring claimant's run.
    #[test]
    fn unowned_lines_are_excluded_from_runs() {
        let mut o = owners(3);
        let a = parse_attr_diff("+++ b/f\n@@ -2,0 +2,1 @@\n+X\n");
        apply_attr_hunks(&mut o, &a["f"], "A");
        let runs = attr_runs(&o);
        assert_eq!(runs.len(), 1);
        assert_eq!(runs[0]["startLine"], 2);
        assert_eq!(runs[0]["endLine"], 2);
    }

    #[test]
    fn zero_work_interval_contributes_nothing() {
        let mut o = owners(3);
        let m = parse_attr_diff("");
        assert!(m.is_empty());
        apply_attr_hunks(&mut o, &[], "A");
        assert_eq!(ids(&o), "...");
        assert!(attr_runs(&o).is_empty());
    }
}
